-- RN Master standalone MC/SATA pilot import. Source: user-provided 1000-question RN master bank.
begin;
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set13-RN-1','Management of Care','Prioritization','single_best_answer','Management of Care • Prioritization • Multiple choice The nurse on a pediatric unit receives report on four children. Which child should the nurse assess first?','A 3-year-old with croup who has a barking cough and no stridor at rest|A 6-year-old with asthma who has become quiet, with SpO2 88% and intercostal retractions|An 8-year-old with a casted forearm fracture who rates pain 5/10|A 6-month-old who is due for scheduled immunizations','B','A child with asthma who becomes quiet with hypoxemia and retractions may be tiring and moving too little air to wheeze, which signals impending respiratory failure. Croup without stridor at rest is mild.','Pediatrics','Management of Care'),
('Set13-RN-2','Health Promotion and Maintenance','Growth and development','single_best_answer','Health Promotion and Maintenance • Growth and development • Multiple choice Which toy is most appropriate for a hospitalized 9-month-old?','A set of small plastic beads|Large, soft stacking cups|A 500-piece puzzle|A board game with small dice','B','Infants explore by mouthing, banging, and stacking. Large, safe toys support motor development without choking risk. Small parts are a choking hazard for children under 3.','Pediatrics','Fundamentals'),
('Set13-RN-3','Health Promotion and Maintenance','Developmental screening','single_best_answer','Health Promotion and Maintenance • Developmental screening • Multiple choice Which finding in an 18-month-old should the nurse report for further developmental evaluation?','Walks independently and climbs stairs with help|Says no words and does not point to show interest|Has frequent temper tantrums|Prefers parallel play','B','Most 18-month-olds say several words and point to share interest. The absence of words, pointing, or joint attention are red flags for language delay or autism spectrum disorder. Tantrums and parallel play are typical toddler behaviors.','Pediatrics','Fundamentals'),
('Set13-RN-4','Health Promotion and Maintenance','Immunizations','single_best_answer','Health Promotion and Maintenance • Immunizations • Multiple choice A 12-month-old is due for immunizations. Which finding would contraindicate giving a vaccine today?','A mild cold with a temperature of 99.8°F (37.7°C)|A history of anaphylaxis after a previous dose of the same vaccine|Currently taking amoxicillin for an ear infection|A sibling at home who is pregnant    ','B','Anaphylaxis to a prior dose or vaccine component is a true contraindication. Mild illness, antibiotic use, and a pregnant household member are not contraindications to routine vaccines.','Pediatrics','Fundamentals'),
('Set13-RN-5','Pharmacological and Parenteral Therapies','Pediatric dosage calculation','single_best_answer','Pharmacological and Parenteral Therapies • Pediatric dosage calculation • Multiple choice A child weighing 15 kg is prescribed amoxicillin 40 mg/kg/day orally in two divided doses. How many milligrams should the nurse give per dose?','150 mg|300 mg|600 mg|750 mg','B','40 mg × 15 kg = 600 mg/day. Divided into two doses, 600 ÷ 2 = 300 mg per dose.','Pediatrics','Pharmacology'),
('Set13-RN-6','Pharmacological and Parenteral Therapies','Safe dose range','single_best_answer','Pharmacological and Parenteral Therapies • Safe dose range • Multiple choice A child weighing 18 kg is prescribed a medication 250 mg every 8 hours. The safe dose range is 20–40 mg/kg/day. What should the nurse do?','Administer the dose, since it is within range|Clarify the prescription with the provider because the daily dose exceeds the safe range|Administer half the dose|Give the dose every 12 hours instead','B','Safe range: 20 × 18 = 360 mg/day to 40 × 18 = 720 mg/day. Prescribed: 250 mg × 3 = 750 mg/day, which exceeds the maximum. The nurse clarifies rather than changing the dose independently.','Pediatrics','Pharmacology'),
('Set13-RN-7','Physiological Adaptation','Kawasaki disease','single_best_answer','Physiological Adaptation • Kawasaki disease • Multiple choice A child with Kawasaki disease received IV immunoglobulin (IVIG) and is taking aspirin. Which statement by the parent indicates understanding of discharge teaching?','"We''ll get the MMR vaccine next week as scheduled."|"We''ll keep follow-up appointments for echocardiograms to check the heart."|"We can give ibuprofen with the aspirin for fever."|"The peeling skin on the fingers means the treatment failed."','B','Coronary artery aneurysms are the major complication, so echocardiograms are repeated. Live vaccines are delayed about 11 months after IVIG. Ibuprofen interferes with aspirin''s antiplatelet effect. Peeling of the fingers and toes is expected during the subacute phase.','Pediatrics','Adult Health'),
('Set13-RN-8','Physiological Adaptation','Intussusception','single_best_answer','Physiological Adaptation • Intussusception • Multiple choice A 10-month-old with suspected intussusception is scheduled for an air enema. Before the procedure, the infant passes a normal brown stool. What should the nurse do?','Proceed with the procedure as scheduled|Report the finding to the provider immediately|Give the infant a bottle of formula|Document the stool only    ','B','A normal stool may mean the intussusception has reduced on its own, which could change the plan. Classic findings include intermittent severe abdominal pain with knees drawn up, a sausage-shaped mass, and "currant jelly" stools.','Pediatrics','Adult Health'),
('Set13-RN-9','Physiological Adaptation','Pyloric stenosis','single_best_answer','Physiological Adaptation • Pyloric stenosis • Multiple choice A 4-week-old has forceful, projectile vomiting after feedings and seems hungry afterward. Which additional finding does the nurse expect?','An olive-shaped mass in the right upper quadrant and metabolic alkalosis|Currant jelly stools|Bile-stained vomitus and metabolic acidosis|Failure to pass meconium','A','Hypertrophy of the pyloric muscle causes nonbilious projectile vomiting, a palpable olive-shaped mass, and loss of gastric acid, which leads to hypochloremic metabolic alkalosis and dehydration.','Pediatrics','Adult Health'),
('Set13-RN-10','Physiological Adaptation','Hirschsprung disease','single_best_answer','Physiological Adaptation • Hirschsprung disease • Multiple choice Which newborn finding should the nurse report because it suggests Hirschsprung disease?','Passing meconium within 24 hours|No meconium passed within 48 hours of birth, with abdominal distention|Yellow, seedy stools on day 4|Transitional stools on day 3','B','Absence of ganglion cells in part of the colon prevents peristalsis, causing delayed meconium passage and distention. Most newborns pass meconium within 24–48 hours.','Pediatrics','Adult Health'),
('Set13-RN-11','Pharmacological and Parenteral Therapies','Cystic fibrosis','single_best_answer','Pharmacological and Parenteral Therapies • Cystic fibrosis • Multiple choice The nurse is teaching the parent of a child with cystic fibrosis about pancreatic enzyme capsules. Which instruction is correct?','"Give the enzymes once a day at bedtime."|"Give the enzymes with every meal and snack."|"Crush the enzyme beads and mix them with hot food."|"Give the enzymes only when stools are greasy."','B','Enzymes are taken with all meals and snacks to digest fats and proteins. Capsules can be opened and the beads sprinkled on a small amount of cool, acidic soft food, but they are not crushed or chewed. A high-calorie, high-protein diet with fat-soluble vitamins is recommended.','Pediatrics','Pharmacology'),
('Set13-RN-12','Physiological Adaptation','Tetralogy of Fallot','single_best_answer','Physiological Adaptation • Tetralogy of Fallot • Multiple choice A toddler with unrepaired tetralogy of Fallot becomes suddenly cyanotic and irritable during a blood draw. What should the nurse do first?','Place the child in a knee-chest position|Lay the child flat on the back|Encourage the child to walk|Give the child a bottle of juice','A','During a hypercyanotic ("tet") spell, knee-chest positioning increases systemic vascular resistance, which reduces right-to-left shunting and improves pulmonary blood flow. Oxygen and calming measures follow.','Pediatrics','Adult Health'),
('Set13-RN-13','Pharmacological and Parenteral Therapies','Pediatric digoxin','single_best_answer','Pharmacological and Parenteral Therapies • Pediatric digoxin • Multiple choice An infant with heart failure is prescribed digoxin. The apical pulse, counted for 1 full minute, is 84/min. What should the nurse do?','Administer the dose|Hold the dose and notify the provider|Give half the dose|Recheck the pulse in 4 hours and give it then    ','B','Digoxin is generally held in infants when the apical pulse is below about 90–110/min (per provider parameters and facility policy). A pulse of 84/min in an infant indicates bradycardia.','Pediatrics','Pharmacology'),
('Set13-RN-14','Health Promotion and Maintenance','Lead poisoning','single_best_answer','Health Promotion and Maintenance • Lead poisoning • Multiple choice Which child is at greatest risk for lead poisoning?','A 2-year-old living in a house built in 1950 with peeling paint|A 10-year-old living in a newly built apartment|A 6-month-old who is exclusively breastfed in a home built in 2010|An adolescent who plays outdoor sports','A','Homes built before 1978 may contain lead-based paint. Toddlers put things in their mouths and absorb lead more readily. Lead exposure causes neurodevelopmental harm, and screening is recommended for at-risk children.','Pediatrics','Fundamentals'),
('Set13-RN-15','Pharmacological and Parenteral Therapies','Acetaminophen overdose','single_best_answer','Pharmacological and Parenteral Therapies • Acetaminophen overdose • Multiple choice A 3-year-old is brought in 2 hours after swallowing an unknown number of children''s acetaminophen tablets. Which antidote does the nurse anticipate?','Naloxone|Acetylcysteine|Flumazenil|Vitamin K','B','Acetylcysteine replenishes glutathione and prevents liver injury. It is most effective within 8 hours of ingestion. A serum acetaminophen level at 4 hours guides treatment.','Pediatrics','Pharmacology'),
('Set13-RN-16','Psychosocial Integrity','Child maltreatment','multiple_response','Psychosocial Integrity • Child maltreatment • Select all that apply Which findings should raise the nurse''s concern about possible child abuse? Select all that apply.','An injury that does not match the history or the child''s developmental ability|Bruises in various stages of healing on the back and buttocks|A spiral fracture of the femur in a 4-month-old who is not yet crawling|A long delay between the injury and seeking care|Retinal hemorrhages in an infant with no history of major trauma|Bruises on the shins of an active 4-year-old','A,B,C,D,E','Inconsistent histories, patterned or multiple-stage bruising in protected areas, fractures in nonambulatory infants, delayed care, and retinal hemorrhages (abusive head trauma) are red flags. Nurses are mandated reporters. Shin bruises are common in active children.','Pediatrics','Mental Health'),
('Set13-RN-17','Safety and Infection Control','Wilms tumor','single_best_answer','Safety and Infection Control • Wilms tumor • Multiple choice A 3-year-old is admitted with a suspected Wilms tumor. Which action is most important for the nurse to include in the plan of care?','Palpate the abdomen every 4 hours|Post a sign at the bedside stating "Do not palpate the abdomen"|Encourage the child to lie prone|Apply heat to the abdomen    ','B','Palpating a Wilms tumor (nephroblastoma) can rupture the capsule and spread tumor cells. Bathing and handling are done carefully.','Pediatrics','Safety & Infection Control'),
('Set13-RN-18','Health Promotion and Maintenance','Scoliosis','single_best_answer','Health Promotion and Maintenance • Scoliosis • Multiple choice An adolescent with scoliosis is prescribed a thoracolumbosacral brace. Which statement indicates understanding?','"I''ll wear it only at night."|"I''ll wear it about 18–23 hours a day, as prescribed, and wear a T-shirt under it."|"I''ll wear it only during sports."|"I''ll stop wearing it if it''s uncomfortable."','B','Bracing works when worn for the prescribed hours, often 18–23 hours daily. A cotton shirt underneath protects the skin. Body image concerns are important to address with adolescents.','Pediatrics','Fundamentals'),
('Set13-RN-19','Psychosocial Integrity','Separation anxiety','single_best_answer','Psychosocial Integrity • Separation anxiety • Multiple choice A hospitalized 2-year-old screams and cries when the parents leave for the night. What is the nurse''s best action?','Tell the parents not to visit because it upsets the child|Encourage the parents to stay when possible and leave a familiar object such as a favorite blanket|Sedate the child|Scold the child for crying  ','B','Separation anxiety peaks in toddlers. Protest (crying) is a normal first stage. Parental presence, rooming-in, familiar objects, and consistent routines reduce distress.','Pediatrics','Mental Health'),
('Set14-RN-1','Management of Care','Prioritization','single_best_answer','Management of Care • Prioritization • Multiple choice The nurse on an inpatient psychiatric unit receives report on four clients. Which client should the nurse see first?','A client with major depression who has been withdrawn for days, is now suddenly calm and cheerful, and gave a watch to a peer|A client with schizophrenia who reports hearing voices commenting on the weather|A client with anorexia nervosa who is refusing to finish breakfast|A client with bipolar disorder who is pacing in the hallway','A','A sudden lift in mood with giving away belongings can indicate that a client with depression has made a decision and plan to die by suicide. Immediate assessment is needed. The other behaviors require attention but are less urgent.','Mental Health','Management of Care'),
('Set14-RN-2','Psychosocial Integrity','Suicide assessment','single_best_answer','Psychosocial Integrity • Suicide assessment • Multiple choice A client says, "Everyone would be better off without me." What is the nurse''s best response?','"Don''t talk like that. Your family loves you."|"Are you having thoughts of killing yourself?"|"Why would you think that?"|"Let''s focus on something more positive."','B','Asking directly about suicidal thoughts is the most important step and does not increase risk. If the client says yes, the nurse asks about a plan, means, and intent. The other responses dismiss, challenge, or avoid the concern.','Mental Health','Mental Health'),
('Set14-RN-3','Safety and Infection Control','Suicide precautions','multiple_response','Safety and Infection Control • Suicide precautions • Select all that apply A client is admitted with a recent suicide attempt and ongoing suicidal ideation. Which interventions should the nurse implement? Select all that apply.','Remove belts, shoelaces, and sharp objects from the room|Maintain continuous one-to-one observation as prescribed|Check that the client swallows oral medications|Assign the client a room far from the nurses'' station for privacy|Search belongings and items brought by visitors per policy|Allow the client to keep a razor for grooming if they promise to be careful','A,B,C,E','Removing potential means, close observation, verifying medication intake (to prevent hoarding), and screening items reduce risk. Clients at high risk are placed near staff, and promises of safety do not replace environmental safety.','Mental Health','Safety & Infection Control'),
('Set14-RN-4','Pharmacological and Parenteral Therapies','Lithium toxicity','single_best_answer','Pharmacological and Parenteral Therapies • Lithium toxicity • Multiple choice A client taking lithium has vomiting, diarrhea, coarse hand tremors, and new confusion. The lithium level is 2.1 mEq/L. What should the nurse do first?','Administer the next scheduled dose|Hold the lithium and notify the provider immediately|Encourage the client to drink a large glass of water and give the dose|Administer an antidiarrheal    ','B','The usual therapeutic range is about 0.6–1.2 mEq/L. A level of 2.1 with neurological signs indicates moderate to severe toxicity. Lithium is held, and treatment may include IV fluids and hemodialysis.','Mental Health','Pharmacology'),
('Set14-RN-5','Pharmacological and Parenteral Therapies','Lithium teaching','single_best_answer','Pharmacological and Parenteral Therapies • Lithium teaching • Multiple choice The nurse is teaching a client who is starting lithium. Which client statement indicates a need for further teaching?','"I''ll keep my salt and fluid intake about the same every day."|"I''ll take ibuprofen whenever I have a headache."|"I''ll have my blood level checked as scheduled."|"I''ll call my provider if I have vomiting or diarrhea."','B','NSAIDs, ACE inhibitors, and thiazide diuretics reduce lithium clearance and can cause toxicity. Consistent sodium and fluid intake keeps levels stable, and dehydration from illness raises levels.','Mental Health','Pharmacology'),
('Set14-RN-6','Pharmacological and Parenteral Therapies','MAOI diet','single_best_answer','Pharmacological and Parenteral Therapies • MAOI diet • Multiple choice A client taking phenelzine, an MAOI, is choosing a meal. Which choice indicates understanding of dietary restrictions?','Aged cheddar cheese and salami on crackers|Fresh roasted chicken with rice and steamed green beans|Pizza with pepperoni and a draft beer|Stir-fry with soy sauce and fermented tofu','B','MAOIs prevent breakdown of tyramine. Aged cheeses, cured meats, tap beer, soy sauce, and fermented foods can trigger a hypertensive crisis. Fresh foods are safe.','Mental Health','Pharmacology'),
('Set14-RN-7','Pharmacological and Parenteral Therapies','Serotonin syndrome','single_best_answer','Pharmacological and Parenteral Therapies • Serotonin syndrome • Multiple choice A client taking sertraline was recently prescribed tramadol. The client is now agitated and diaphoretic with a temperature of 102.2°F (39°C), HR 124/min, diarrhea, and muscle twitching (clonus). What does the nurse suspect?','Neuroleptic malignant syndrome|Serotonin syndrome|Anticholinergic toxicity|Alcohol withdrawal','B','Combining serotonergic drugs such as SSRIs with tramadol, triptans, linezolid, or St. John''s wort can cause serotonin syndrome. It features agitation, autonomic instability, hyperthermia, GI symptoms, and neuromuscular hyperactivity such as clonus. The drugs are stopped and supportive care is given.','Mental Health','Pharmacology'),
('Set14-RN-8','Pharmacological and Parenteral Therapies','Neuroleptic malignant syndrome','single_best_answer','Pharmacological and Parenteral Therapies • Neuroleptic malignant syndrome • Multiple choice A client started haloperidol 3 days ago. The client now has a temperature of 104°F (40°C), severe "lead-pipe" muscle rigidity, fluctuating BP, confusion, and an elevated creatine kinase. What should the nurse do first?','Administer the next dose of haloperidol|Hold the antipsychotic and notify the provider immediately|Encourage ambulation|Apply warm blankets    ','B','These findings indicate neuroleptic malignant syndrome, a life-threatening reaction. The antipsychotic is stopped, and care includes cooling, hydration, and possibly dantrolene or bromocriptine.','Mental Health','Pharmacology'),
('Set14-RN-9','Pharmacological and Parenteral Therapies','Clozapine','single_best_answer','Pharmacological and Parenteral Therapies • Clozapine • Multiple choice A client taking clozapine reports a sore throat and fever. What should the nurse do?','Tell the client this is a common cold|Hold the dose and notify the provider, anticipating a CBC with absolute neutrophil count|Give an extra dose|Encourage warm salt-water gargles only','B','Clozapine can cause severe neutropenia (agranulocytosis). Signs of infection require prompt ANC evaluation. Regular ANC monitoring is required throughout therapy.','Mental Health','Pharmacology'),
('Set14-RN-10','Pharmacological and Parenteral Therapies','Acute dystonia','single_best_answer','Pharmacological and Parenteral Therapies • Acute dystonia • Multiple choice Several hours after receiving IM haloperidol, a client develops a twisted neck, eyes fixed upward, and difficulty speaking. Which medication does the nurse anticipate giving?','Benztropine or diphenhydramine IM or IV|Additional haloperidol|Lithium|Propranolol orally','A','Acute dystonia is an extrapyramidal side effect that responds rapidly to anticholinergic agents such as benztropine or diphenhydramine. Laryngeal dystonia can threaten the airway.','Mental Health','Pharmacology'),
('Set14-RN-11','Psychosocial Integrity','Hallucinations','single_best_answer','Psychosocial Integrity • Hallucinations • Multiple choice A client with schizophrenia says, "Do you hear the voices telling me I''m evil?" What is the nurse''s best response?','"Yes, I hear them too."|"I don''t hear voices, but I understand they seem very real to you. What are they saying?"|"There are no voices. Stop imagining things."|"Let''s not talk about the voices."','B','The nurse presents reality without arguing and acknowledges the client''s experience. Asking what the voices say assesses for command hallucinations that could lead to harm.','Mental Health','Mental Health'),
('Set14-RN-12','Basic Care and Comfort','Mania','single_best_answer','Basic Care and Comfort • Mania • Multiple choice A client in an acute manic episode will not sit down to eat and has lost weight. Which intervention is most appropriate?','Insist that the client sit at the table for full meals|Provide high-calorie finger foods and fluids the client can eat while moving|Serve meals in the busy dining room to encourage socializing|Withhold snacks until the client eats a full meal','B','Portable, high-calorie foods meet the increased energy needs of a client who is too distractible to sit. A low-stimulation environment also helps.','Mental Health','Adult Health'),
('Set14-RN-13','Physiological Adaptation','Bulimia nervosa','single_best_answer','Physiological Adaptation • Bulimia nervosa • Multiple choice A client with bulimia nervosa who purges several times a day reports palpitations and muscle weakness. Which lab result should the nurse report immediately?','Potassium 2.7 mEq/L|Sodium 138 mEq/L|Glucose 92 mg/dL|Hemoglobin 12.4 g/dL    ','A','Repeated vomiting causes hypokalemia and metabolic alkalosis, which can lead to fatal dysrhythmias. Palpitations and weakness are consistent with significant hypokalemia.','Mental Health','Adult Health'),
('Set14-RN-14','Psychosocial Integrity','Borderline personality disorder','single_best_answer','Psychosocial Integrity • Borderline personality disorder • Multiple choice A client with borderline personality disorder tells the nurse, "You''re the only one who understands me. The night nurse is terrible." What is the best approach?','Agree and promise to always be the client''s nurse|Maintain consistent limits and communicate with the team to present a unified approach|Share the client''s comments with the night nurse privately and ask them to change|Avoid the client','B','This is splitting, a common defense in borderline personality disorder. Consistent limits and team communication prevent staff division and help the client learn stable relationships.','Mental Health','Mental Health'),
('Set14-RN-16','Management of Care','Restraints','single_best_answer','Management of Care • Restraints • Multiple choice A client is placed in physical restraints after assaulting a staff member. Which action by the nurse is correct?','Obtain a prescription that is renewed daily without reassessment|Monitor the client at frequent intervals per policy (for example, every 15 minutes) and assess circulation, skin, hydration, and toileting needs|Keep the client restrained until the next day to ensure safety|Tie the restraints to the side rails','B','Restraints are a last resort, used for the shortest time with time-limited orders and face-to-face evaluation per regulations. Restraints are tied to the bed frame, not side rails, and removed as soon as the client is safe.','Mental Health','Management of Care'),
('Set14-RN-17','Psychosocial Integrity','Posttraumatic stress disorder','single_best_answer','Psychosocial Integrity • Posttraumatic stress disorder • Multiple choice A veteran with PTSD startles and becomes agitated when a tray is dropped loudly in the hallway. Which approach by the nurse is most therapeutic?','Tell the client there''s nothing to be afraid of|Approach calmly, orient the client to the present, and offer a quiet space|Touch the client firmly on the shoulder without warning|Ask the client to describe the trauma in detail now    ','B','Trauma-informed care emphasizes safety and grounding. The nurse avoids sudden touch and does not push the client to recount trauma during acute distress.','Mental Health','Mental Health'),
('Set14-RN-18','Pharmacological and Parenteral Therapies','Opioid overdose','single_best_answer','Pharmacological and Parenteral Therapies • Opioid overdose • Multiple choice A client is found unresponsive with pinpoint pupils and RR 4/min after suspected fentanyl use. Naloxone 4 mg intranasal is given, and the client wakes up. Why must the nurse continue close monitoring?','Naloxone causes permanent sedation|Naloxone may wear off before the opioid, so respiratory depression can return|Naloxone causes hypoglycemia|Monitoring is not needed after the client wakes up','B','Naloxone''s duration can be shorter than that of many opioids, especially potent or long-acting ones, so repeat doses may be needed. Naloxone can also precipitate acute withdrawal.','Mental Health','Pharmacology'),
('Set14-RN-19','Reduction of Risk Potential','Electroconvulsive therapy','single_best_answer','Reduction of Risk Potential • Electroconvulsive therapy • Multiple choice A client scheduled for electroconvulsive therapy (ECT) asks about side effects. Which response by the nurse is accurate?','"You''ll have permanent memory loss."|"Short-term confusion and some memory loss around the time of treatment are common and usually improve."|"You will be awake and feel the seizure."|"There are no side effects."  ','B','ECT is performed under brief general anesthesia with a muscle relaxant. Temporary confusion, headache, and short-term memory loss are common. The client is NPO beforehand, and vital signs and orientation are monitored afterward.','Mental Health','Adult Health'),
('Set15-RN-1','Management of Care','Medication prioritization','single_best_answer','Management of Care • Medication prioritization • Multiple choice At 0900, the nurse has several medications to administer. Which medication should the nurse give first?','A STAT dose of IV ceftriaxone for a client newly diagnosed with sepsis|A scheduled oral stool softener|PRN acetaminophen for a headache rated 3/10|A daily oral multivitamin','A','Timely antibiotics in sepsis reduce mortality, and STAT medications take priority. The other medications are routine or for mild symptoms.','Pharmacology','Management of Care'),
('Set15-RN-2','Pharmacological and Parenteral Therapies','Dosage calculation: mcg/kg/min','single_best_answer','Pharmacological and Parenteral Therapies • Dosage calculation: mcg/kg/min • Multiple choice A client weighing 80 kg is prescribed dopamine at 5 mcg/kg/min. The bag contains dopamine 400 mg in 250 mL. At what rate in mL/hr should the nurse set the pump?','7.5 mL/hr|15 mL/hr|24 mL/hr|30 mL/hr','B','Concentration: 400 mg ÷ 250 mL = 1.6 mg/mL = 1,600 mcg/mL. Dose: 5 mcg × 80 kg = 400 mcg/min × 60 = 24,000 mcg/hr. Rate: 24,000 ÷ 1,600 = 15 mL/hr.','Pharmacology','Pharmacology'),
('Set15-RN-3','Pharmacological and Parenteral Therapies','Dosage calculation: insulin infusion','single_best_answer','Pharmacological and Parenteral Therapies • Dosage calculation: insulin infusion • Multiple choice A client weighing 70 kg is prescribed a regular insulin infusion at 0.1 unit/kg/hr. The bag contains 100 units of regular insulin in 100 mL of 0.9% sodium chloride. At what rate should the nurse set the pump?','0.7 mL/hr|7 mL/hr|10 mL/hr|70 mL/hr','B','Dose: 0.1 unit × 70 kg = 7 units/hr. Concentration: 100 units ÷ 100 mL = 1 unit/mL. Rate: 7 mL/hr. Insulin is a high-alert medication that requires an independent double check.','Pharmacology','Pharmacology'),
('Set15-RN-4','Pharmacological and Parenteral Therapies','Dosage calculation: unit conversion','single_best_answer','Pharmacological and Parenteral Therapies • Dosage calculation: unit conversion • Multiple choice Levothyroxine 0.15 mg PO is prescribed. The pharmacy supplies 75-mcg tablets. How many tablets should the nurse give?','0.5 tablet|1 tablet|2 tablets|3 tablets    ','C','0.15 mg = 150 mcg. 150 mcg ÷ 75 mcg per tablet = 2 tablets.','Pharmacology','Pharmacology'),
('Set15-RN-5','Pharmacological and Parenteral Therapies','Dosage calculation: oral liquid','single_best_answer','Pharmacological and Parenteral Therapies • Dosage calculation: oral liquid • Multiple choice Cephalexin 250 mg PO is prescribed. The suspension is labeled 125 mg/5 mL. How many milliliters should the nurse give?','2.5 mL|5 mL|10 mL|12.5 mL','C','250 mg ÷ 125 mg × 5 mL = 10 mL.','Pharmacology','Pharmacology'),
('Set15-RN-6','Pharmacological and Parenteral Therapies','Dosage calculation: reconstitution','single_best_answer','Pharmacological and Parenteral Therapies • Dosage calculation: reconstitution • Multiple choice Ceftriaxone 500 mg IM is prescribed. The nurse reconstitutes a 1-g vial as directed, producing a concentration of 250 mg/mL. How many milliliters should the nurse administer?','0.5 mL|1 mL|2 mL|4 mL','C','500 mg ÷ 250 mg/mL = 2 mL. The nurse labels the reconstituted vial with the date, time, concentration, and initials.','Pharmacology','Pharmacology'),
('Set15-RN-7','Pharmacological and Parenteral Therapies','Antidotes','single_best_answer','Pharmacological and Parenteral Therapies • Antidotes • Multiple choice A client with heart failure has nausea, yellow-tinged vision, HR 42/min, and a digoxin level of 3.4 ng/mL. Which medication does the nurse anticipate?','Protamine sulfate|Digoxin immune fab|Flumazenil|Naloxone','B','Digoxin immune fab binds digoxin and reverses life-threatening toxicity. The nurse also monitors potassium, since hypokalemia increases toxicity and potassium can shift after reversal.','Pharmacology','Pharmacology'),
('Set15-RN-9','Pharmacological and Parenteral Therapies','ACE inhibitors','single_best_answer','Pharmacological and Parenteral Therapies • ACE inhibitors • Multiple choice A client who started lisinopril 2 weeks ago arrives with swelling of the lips and tongue and difficulty speaking. What is the nurse''s priority?','Administer the next dose of lisinopril|Assess and protect the airway, and prepare for emergency airway management|Apply ice to the lips|Reassure the client that this is a mild side effect','B','Angioedema from ACE inhibitors can cause airway obstruction. The drug is stopped permanently. A dry cough is a more common, less dangerous side effect.','Pharmacology','Pharmacology'),
('Set15-RN-10','Safety and Infection Control','High-alert medications','single_best_answer','Safety and Infection Control • High-alert medications • Multiple choice Which medication typically requires an independent double check by a second licensed nurse before administration?','Oral docusate|IV insulin infusion|Oral multivitamin|Topical hydrocortisone cream','B','High-alert medications such as insulin, heparin, opioid infusions, and concentrated electrolytes carry a high risk of serious harm if given in error. Many facilities require independent double checks.','Pharmacology','Safety & Infection Control'),
('Set15-RN-11','Safety and Infection Control','Client identification','single_best_answer','Safety and Infection Control • Client identification • Multiple choice Before administering medications, which action best confirms the client''s identity?','Checking the room number and bed|Asking "Are you Mr. Jones?"|Comparing two identifiers, such as full name and date of birth, with the MAR and scanning the ID band|Asking the roommate to confirm the client''s name','C','Two client-specific identifiers are required. Room numbers are not identifiers, and yes-or-no questions can lead to errors if the client is confused or hard of hearing.','Pharmacology','Safety & Infection Control'),
('Set15-RN-12','Safety and Infection Control','Do-not-use abbreviations','single_best_answer','Safety and Infection Control • Do-not-use abbreviations • Multiple choice Which medication prescription should the nurse clarify before administering?','Heparin 5,000 units subcutaneously every 12 hours|Morphine 2.0 mg IV every 4 hours as needed for pain|Metoprolol tartrate 25 mg PO twice daily|Furosemide 40 mg IV once daily','B','A trailing zero (2.0 mg) can be misread as 20 mg, a tenfold overdose. The Joint Commission''s "Do Not Use" list also includes "U" for units, "QD," and "MS" for morphine.','Pharmacology','Safety & Infection Control'),
('Set15-RN-13','Management of Care','Controlled substances','single_best_answer','Management of Care • Controlled substances • Multiple choice The nurse draws up 4 mg of morphine from a 10-mg carpuject but the client needs only 2 mg. What should the nurse do with the remaining medication?','Save it in the medication room for the next dose|Waste it in the presence of another licensed nurse and have both document the waste|Discard it in the sharps container without a witness|Give it to the client later    ','B','Controlled substance waste must be witnessed and documented by two licensed staff to prevent diversion and ensure accountability.','Pharmacology','Management of Care'),
('Set15-RN-14','Management of Care','Medication errors','single_best_answer','Management of Care • Medication errors • Multiple choice The nurse realizes a client was given metoprolol intended for the client''s roommate. What should the nurse do first?','Complete an incident report|Assess the client, including vital signs|Notify the pharmacy|Document the error in the client''s chart as an incident','B','Client safety comes first. The nurse assesses for adverse effects such as bradycardia and hypotension, then notifies the provider and follows the facility''s reporting process. Incident reports are not referenced in the medical record.','Pharmacology','Management of Care'),
('Set15-RN-15','Reduction of Risk Potential','Therapeutic drug monitoring','single_best_answer','Reduction of Risk Potential • Therapeutic drug monitoring • Multiple choice When should the nurse obtain a vancomycin trough level for a client receiving intermittent dosing?','Immediately after the infusion ends|Within 30 minutes before the next scheduled dose|Two hours after the dose|At any time of day','B','A trough is the lowest drug level, just before the next dose. Many facilities now use AUC-based dosing, but when a trough is prescribed, timing must be accurate for dose adjustment.','Pharmacology','Adult Health'),
('Set15-RN-16','Pharmacological and Parenteral Therapies','Older adults','single_best_answer','Pharmacological and Parenteral Therapies • Older adults • Multiple choice Which principle guides medication dosing in older adults?','Start with higher doses to overcome slower absorption|Start low and go slow, because renal and hepatic clearance are often reduced|Older adults need fewer monitoring visits|Drug interactions are less common with age','B','Age-related declines in kidney and liver function, along with changes in body composition, increase drug levels and the risk of adverse effects. Polypharmacy also raises interaction risk.','Pharmacology','Pharmacology'),
('Set15-RN-17','Safety and Infection Control','Potentially inappropriate medications','single_best_answer','Safety and Infection Control • Potentially inappropriate medications • Multiple choice An 84-year-old client asks for something to help with sleep. Which PRN prescription should the nurse question?','Melatonin 3 mg at bedtime|Diphenhydramine 50 mg at bedtime|Nonpharmacological sleep measures|Acetaminophen for pain that is keeping the client awake','B','Diphenhydramine is highly anticholinergic and is on the AGS Beers Criteria list of drugs to avoid in older adults because it causes confusion, urinary retention, constipation, and falls.','Pharmacology','Safety & Infection Control'),
('Set15-RN-18','Pharmacological and Parenteral Therapies','Drug interactions','single_best_answer','Pharmacological and Parenteral Therapies • Drug interactions • Multiple choice A client with a stable INR on warfarin is newly prescribed ciprofloxacin. What should the nurse anticipate?','No change in monitoring|More frequent INR monitoring because of an increased bleeding risk|Doubling the warfarin dose|Stopping warfarin permanently    ','B','Many antibiotics, including fluoroquinolones and metronidazole, increase warfarin''s effect and raise the INR. Closer monitoring and possible dose adjustment are needed.','Pharmacology','Pharmacology'),
('Set15-RN-19','Safety and Infection Control','Patient-controlled analgesia','single_best_answer','Safety and Infection Control • Patient-controlled analgesia • Multiple choice A client is using a morphine PCA pump after surgery. The client''s daughter asks if she can press the button while her mother sleeps so she stays comfortable. What is the nurse''s best response?','"Yes, that will keep her pain under control."|"Only your mother should press the button. If she is asleep, she doesn''t need more medication right now, and extra doses could slow her breathing."|"Press it only once every hour."|"Only press it if she is groaning."  ','B','PCA safety depends on the client being awake enough to press the button. "PCA by proxy" bypasses this safeguard and can cause oversedation and respiratory depression.','Pharmacology','Safety & Infection Control'),
('Set16-RN-1','Management of Care','Disaster triage','single_best_answer','Management of Care • Disaster triage • Multiple choice During a mass casualty incident, the nurse uses the START triage system. A victim is walking in circles, is confused, has RR 34/min, and has a capillary refill of 4 seconds. How should the nurse triage this victim?','Green (minor)|Yellow (delayed)|Red (immediate)|Black (expectant/deceased)','C','In START, RR over 30, capillary refill over 2 seconds (or no radial pulse), or inability to follow simple commands means immediate (red) priority. Ambulatory status alone does not determine the category when these findings are present.','Management of Care','Management of Care'),
('Set16-RN-2','Management of Care','Disaster planning','single_best_answer','Management of Care • Disaster planning • Multiple choice The hospital activates its disaster plan and needs to open beds. Which client is most appropriate for the nurse to recommend for early discharge?','A client 3 days after an uncomplicated appendectomy who is ambulating and eating|A client admitted yesterday with an acute MI|A client receiving an insulin infusion for DKA|A client with a new chest tube','A','Stable clients who can safely continue recovery at home are discharged first during a surge. The other clients need ongoing acute care.','Management of Care','Management of Care'),
('Set16-RN-3','Management of Care','Assignment','single_best_answer','Management of Care • Assignment • Multiple choice Which client assignment is most appropriate for the LPN/VN?','A client with a long-term tracheostomy who needs routine suctioning and scheduled oral medications|A client newly admitted with chest pain who needs an admission assessment|A client receiving a blood transfusion for the first time|A client with a new diagnosis who needs a discharge teaching plan developed','A','LPNs/VNs care for stable clients with predictable outcomes and perform routine procedures. Admission assessments, the first transfusion, and developing teaching plans require RN assessment and judgment.','Management of Care','Management of Care'),
('Set16-RN-4','Management of Care','Five rights of delegation','single_best_answer','Management of Care • Five rights of delegation • Multiple choice The RN delegates vital signs to an assistive personnel. Which instruction best demonstrates the right communication?','"Take everyone''s vitals."|"Take vital signs on Rooms 3 and 5 by 0800 and tell me right away if any systolic BP is below 100 or above 160, or HR is above 110."|"Check vitals when you have time."|"Let me know if anything seems off."    ','B','The five rights of delegation are right task, circumstance, person, direction/communication, and supervision/evaluation. Clear communication includes specific clients, timing, and parameters to report.','Management of Care','Management of Care'),
('Set16-RN-5','Management of Care','Float staff','single_best_answer','Management of Care • Float staff • Multiple choice A pediatric nurse is floated to an adult medical-surgical unit. Which assignment is most appropriate?','A client receiving a titrated IV antiarrhythmic infusion|A stable adult client with pneumonia receiving IV antibiotics|A client in the first hour after a thyroidectomy|A client with a new tracheostomy','B','Float nurses should receive stable clients whose care uses transferable skills. Complex or specialty-specific care should go to nurses experienced on that unit.','Management of Care','Management of Care'),
('Set16-RN-6','Management of Care','Conflict resolution','single_best_answer','Management of Care • Conflict resolution • Multiple choice An assistive personnel refuses a task the RN delegated, saying, "That''s not my job." What is the RN''s best initial action?','Report the AP to the manager immediately|Speak with the AP privately to understand the reason for the refusal|Complete the task and say nothing|Discuss the problem at the team huddle in front of others','B','Addressing the issue privately and directly identifies whether there is a knowledge gap, workload issue, or misunderstanding. Escalation follows if the problem is not resolved.','Management of Care','Management of Care'),
('Set16-RN-7','Management of Care','Informed consent','single_best_answer','Management of Care • Informed consent • Multiple choice The nurse is witnessing a client''s signature on a surgical consent form. The client says, "I''m not sure what the doctor is going to remove." What should the nurse do?','Explain the surgery in detail and have the client sign|Hold the consent and notify the surgeon that the client needs more information|Have the family member sign instead|Tell the client that the doctor knows best','B','The provider is responsible for explaining the procedure, risks, benefits, and alternatives. The nurse witnesses the signature and confirms understanding. If the client does not understand, the nurse notifies the provider before consent is signed.','Management of Care','Management of Care'),
('Set16-RN-8','Management of Care','Advance directives','single_best_answer','Management of Care • Advance directives • Multiple choice A client with a do-not-resuscitate (DNR) order develops pneumonia. Which action by the nurse is appropriate?','Withhold antibiotics because the client is DNR|Provide all prescribed treatments, including antibiotics, unless the client''s directives specify otherwise|Stop all nursing care|Transfer the client to hospice without discussion    ','B','A DNR order applies only to CPR in the event of cardiopulmonary arrest. It does not mean withholding other appropriate treatment unless the client''s goals or directives state otherwise.','Management of Care','Management of Care'),
('Set16-RN-9','Management of Care','Confidentiality','single_best_answer','Management of Care • Confidentiality • Multiple choice Which action by a nurse violates client privacy under HIPAA?','Discussing a client''s condition with the care team at the nurses'' station in a quiet voice|Discussing a client''s diagnosis with a coworker in a crowded elevator|Sharing information with a family member the client has listed as authorized|Logging out of the computer after charting','B','Discussing identifiable client information in public areas risks unauthorized disclosure. Sharing with authorized people and securing records protect privacy.','Management of Care','Management of Care'),
('Set16-RN-10','Management of Care','Leaving against medical advice','single_best_answer','Management of Care • Leaving against medical advice • Multiple choice A competent adult client wants to leave the hospital against medical advice. What should the nurse do?','Restrain the client until the provider arrives|Explain the risks, notify the provider, and ask the client to sign an AMA form, documenting the conversation|Take the client''s clothes to prevent them from leaving|Call security to prevent the client from leaving','B','Competent adults have the right to refuse treatment. Detaining them is false imprisonment. The nurse ensures informed refusal and documents it. The client may leave even if they decline to sign.','Management of Care','Management of Care'),
('Set16-RN-11','Management of Care','Incident reports','single_best_answer','Management of Care • Incident reports • Multiple choice A client falls while walking to the bathroom. Which action regarding the incident report is correct?','Write "incident report completed" in the medical record|Complete the report with objective facts and keep it out of the medical record|Include opinions about who was at fault|Give a copy to the client','B','Incident reports are quality improvement tools. They contain factual, objective descriptions and are not referenced in or filed with the medical record. The fall and assessment findings are documented in the chart.','Management of Care','Management of Care'),
('Set16-RN-12','Management of Care','Documentation','single_best_answer','Management of Care • Documentation • Multiple choice The nurse realizes a charting error was made in a paper record. How should the nurse correct it?','Use correction fluid and rewrite the entry|Draw a single line through the error, write "error" or "mistaken entry," and initial and date it|Tear out the page|Scribble over the entry so it can''t be read','B','Corrections must keep the original entry readable to maintain the legal integrity of the record. Electronic records use the system''s amendment function.','Management of Care','Management of Care'),
('Set16-RN-13','Management of Care','Negligence','single_best_answer','Management of Care • Negligence • Multiple choice Which situation best illustrates nursing malpractice?','A nurse gives a medication as prescribed, and the client has an unexpected allergic reaction|A nurse fails to raise the bed rails for a sedated client on fall precautions, and the client falls and fractures a hip|A client refuses a treatment after being informed of the risks|A nurse follows facility policy for a procedure    ','B','Malpractice requires a duty, breach of the standard of care, causation, and resulting harm. Failing to implement ordered fall precautions for a sedated client, causing injury, meets all four elements.','Management of Care','Management of Care'),
('Set16-RN-14','Management of Care','Impaired colleague','single_best_answer','Management of Care • Impaired colleague • Multiple choice The nurse notices that a coworker smells of alcohol and has slurred speech at the start of the shift. What should the nurse do?','Ignore it to avoid conflict|Report the concern to the charge nurse or supervisor immediately|Cover the coworker''s assignment and say nothing|Post about it on social media','B','Client safety requires reporting an impaired colleague through the chain of command. Many facilities and boards offer peer assistance programs.','Management of Care','Management of Care'),
('Set16-RN-15','Management of Care','Ethical principles','single_best_answer','Management of Care • Ethical principles • Multiple choice A client who is a Jehovah''s Witness refuses a blood transfusion. The nurse supports the decision and explores acceptable alternatives with the provider. Which ethical principle is the nurse upholding?','Beneficence|Autonomy|Justice|Fidelity','B','Autonomy is respect for a competent client''s right to make informed decisions about their own care, even when others disagree.','Management of Care','Management of Care'),
('Set16-RN-16','Management of Care','SBAR communication','single_best_answer','Management of Care • SBAR communication • Multiple choice The nurse calls the provider using SBAR about a client with worsening shortness of breath. Which statement is the "recommendation"?','"This is Jane, the nurse caring for Mr. Lee in Room 12."|"His SpO2 dropped to 88% and he has new crackles."|"He was admitted 2 days ago with pneumonia."|"I''d like you to come evaluate him and consider a chest x-ray and a diuretic."','D','SBAR: Situation (who and what is happening), Background (history), Assessment (findings and concerns), and Recommendation (what the nurse is requesting).','Management of Care','Management of Care'),
('Set16-RN-17','Safety and Infection Control','Verbal and telephone orders','single_best_answer','Safety and Infection Control • Verbal and telephone orders • Multiple choice A provider gives the nurse a telephone order for a medication. Which action is correct?','Write the order down later from memory|Write down the order and read it back to the provider for confirmation|Have another nurse listen and give the medication without documenting|Ask the pharmacist to take the order    ','B','The read-back process reduces communication errors. Telephone orders are documented and signed by the provider according to policy.','Management of Care','Safety & Infection Control'),
('Set16-RN-18','Management of Care','Quality improvement','single_best_answer','Management of Care • Quality improvement • Multiple choice A client receives a tenfold overdose of insulin that results in serious harm. The facility conducts a root cause analysis. What is the primary purpose of this process?','To identify which nurse should be disciplined|To identify system and process failures that contributed to the event and prevent recurrence|To prepare for a lawsuit|To document the event in the client''s chart','B','Root cause analysis examines the systems and processes behind sentinel events, supporting a just culture focused on safety improvements rather than blame.','Management of Care','Management of Care'),
('Set16-RN-19','Management of Care','Consent and minors','single_best_answer','Management of Care • Consent and minors • Multiple choice Which minor can legally provide consent for their own surgical procedure in most U.S. states?','A 16-year-old who lives with their parents|A 17-year-old who is legally emancipated|A 15-year-old whose parents are traveling|A 14-year-old who has a part-time job  ','B','Emancipated minors, such as those who are married, in the military, or court-emancipated, can consent to their own care. Some states allow minors to consent to specific services like STI treatment or contraception.','Management of Care','Management of Care'),
('Set17-RN-1','Safety and Infection Control','Fire extinguisher use','single_best_answer','Safety and Infection Control • Fire extinguisher use • Multiple choice The nurse needs to use a fire extinguisher on a small trash can fire. Which sequence is correct?','Aim at the top of the flames, pull the pin, squeeze, and hold still|Pull the pin, aim at the base of the fire, squeeze the handle, and sweep side to side|Squeeze the handle, pull the pin, sweep, and aim|Sweep, aim, pull, squeeze','B','PASS: Pull, Aim at the base, Squeeze, Sweep. Extinguishing is the last step of RACE (Rescue, Alarm, Contain, Extinguish) and is attempted only for small, contained fires.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-2','Safety and Infection Control','MRI safety','single_best_answer','Safety and Infection Control • MRI safety • Multiple choice A client is scheduled for an MRI. Which finding should the nurse report to the radiology department before the test?','The client had a flu shot last month|The client has a permanent pacemaker|The client is allergic to penicillin|The client ate breakfast','B','The MRI''s magnetic field can affect pacemakers and other implanted metal devices. Many modern devices are MRI-conditional but require specific protocols. All metal objects are removed before the scan.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-3','Safety and Infection Control','Electrical safety','single_best_answer','Safety and Infection Control • Electrical safety • Multiple choice The nurse notices the power cord on a client''s IV pump is frayed. What should the nurse do?','Wrap the frayed area with tape|Remove the pump from service, label it, and report it to biomedical engineering|Continue using it until the shift ends|Unplug it only when the client is sleeping','B','Damaged electrical equipment can cause shocks or fires. It is removed from use, tagged as defective, and replaced.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-4','Safety and Infection Control','Surgical safety','single_best_answer','Safety and Infection Control • Surgical safety • Multiple choice When should the surgical team perform the "time-out" to prevent wrong-site surgery?','The day before surgery|Immediately before the incision, with all team members pausing to confirm the client, procedure, and site|During recovery in the PACU|Only if the surgeon requests it    ','B','The Universal Protocol includes preprocedure verification, site marking by the person performing the procedure with the client''s involvement, and a time-out immediately before starting.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-5','Safety and Infection Control','Surgical counts','single_best_answer','Safety and Infection Control • Surgical counts • Multiple choice At the end of surgery, the sponge count is incorrect. What should the circulating nurse do?','Document the discrepancy and let the team close the incision|Notify the surgeon, repeat the count, and follow the facility protocol, which may include an x-ray before closure|Assume the sponge was discarded|Ignore it if only one sponge is missing','B','Retained surgical items are preventable sentinel events. A count discrepancy requires immediate communication, a recount, a search, and imaging per policy before the client leaves the OR.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-6','Safety and Infection Control','Sterile technique','multiple_response','Safety and Infection Control • Sterile technique • Select all that apply Which principles of sterile technique should the nurse follow? Select all that apply.','Only items above waist level are considered sterile|The 1-inch (2.5-cm) border around a sterile field is considered unsterile|Keep the sterile field in view at all times|If sterility is in doubt, consider the item contaminated|Reaching across the sterile field is acceptable if the nurse is careful|Turning your back on a sterile field is acceptable if it is brief','A,B,C,D','Items below the waist, the outer border, anything out of view, and questionable items are considered unsterile. Reaching across the field and turning away risk contamination.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-7','Safety and Infection Control','CLABSI prevention','multiple_response','Safety and Infection Control • CLABSI prevention • Select all that apply Which interventions help prevent central line-associated bloodstream infection? Select all that apply.','Perform hand hygiene before accessing the line|Scrub the needleless connector hub with antiseptic before each access|Change a transparent dressing at least every 7 days and whenever it is damp, loose, or soiled|Assess daily whether the line is still needed|Replace the central line routinely every 72 hours|Apply antibiotic ointment to the insertion site routinely','A,B,C,D','Hand hygiene, hub disinfection ("scrub the hub"), proper dressing care with chlorhexidine, and prompt removal reduce CLABSI. Routine catheter replacement and routine antibiotic ointment are not recommended.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-8','Safety and Infection Control','Surgical site infection prevention','single_best_answer','Safety and Infection Control • Surgical site infection prevention • Multiple choice Which action related to preventing surgical site infection requires the nurse to intervene?','The client showers with chlorhexidine the night before surgery|An assistive personnel shaves the surgical site with a razor the night before surgery|Prophylactic antibiotics are given within 60 minutes before the incision|Normothermia is maintained during surgery    ','B','Razor shaving causes microabrasions that increase infection risk. If hair removal is needed, clippers are used close to the time of surgery. Glucose control is also part of prevention.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-9','Safety and Infection Control','Bioterrorism','single_best_answer','Safety and Infection Control • Bioterrorism • Multiple choice Several clients arrive with suspected inhalation anthrax after exposure to a suspicious powder. Which precautions does the nurse use?','Airborne precautions in negative-pressure rooms|Standard precautions, because inhalation anthrax is not spread person-to-person|Droplet precautions only|Strict reverse isolation','B','Inhalation anthrax is not transmitted person-to-person, so standard precautions are used. Decontamination of exposed people and surfaces follows public health guidance. Smallpox, in contrast, requires airborne and contact precautions.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-10','Safety and Infection Control','Radiation decontamination','single_best_answer','Safety and Infection Control • Radiation decontamination • Multiple choice Victims of a radiological "dirty bomb" arrive at the emergency department. After life-threatening injuries are addressed, which action is the most effective initial decontamination step?','Scrubbing the skin vigorously with a brush|Removing the victims'' clothing and placing it in labeled bags|Applying lotion to the skin|Waiting for radiation levels to be measured before any action','B','Removing outer clothing eliminates most external contamination. Gentle washing with soap and water follows, avoiding skin abrasion, which could allow internal contamination. Life-saving care is never delayed for decontamination.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-11','Safety and Infection Control','Hazardous materials','single_best_answer','Safety and Infection Control • Hazardous materials • Multiple choice A container of an unfamiliar cleaning chemical spills in the utility room. What should the nurse do first?','Wipe it up with paper towels immediately|Keep people away from the area and consult the Safety Data Sheet (SDS) for handling instructions|Pour water on it to dilute it|Leave it for housekeeping without warning anyone','B','The SDS provides hazard, PPE, and cleanup information. Securing the area protects staff and clients. Mixing chemicals with water can cause dangerous reactions.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-12','Safety and Infection Control','Hazardous drug spill','single_best_answer','Safety and Infection Control • Hazardous drug spill • Multiple choice A bag of IV chemotherapy leaks onto the floor. What should the nurse do?','Clean it with regular paper towels and trash|Obtain the chemotherapy spill kit, put on the required PPE, and contain and clean the spill per protocol|Mop it with the unit mop|Call the family to help    ','B','Hazardous drug spills require spill kits with absorbent materials, chemotherapy-tested gloves, gowns, eye protection, and respiratory protection as indicated. Waste goes in hazardous drug containers, and the spill is reported.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-13','Safety and Infection Control','Safe patient handling','single_best_answer','Safety and Infection Control • Safe patient handling • Multiple choice A client who weighs 120 kg and cannot bear weight needs to move from the bed to a chair. What should the nurse do?','Lift the client with one assistant using good body mechanics|Use a mechanical lift with at least two trained staff members|Have the client pivot using a gait belt|Wait until the client can stand','B','Safe patient handling programs use mechanical lifts for dependent clients to prevent injury to staff and clients. The nurse verifies the lift''s weight capacity and sling size.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-14','Health Promotion and Maintenance','Home safety','single_best_answer','Health Promotion and Maintenance • Home safety • Multiple choice The nurse is teaching an older adult about preventing burns at home. Which instruction is most appropriate?','"Set your water heater to 140°F (60°C)."|"Set your water heater to 120°F (49°C) or lower and test the water before bathing."|"Use a heating pad on high while sleeping."|"Remove smoke detector batteries to prevent false alarms."','B','Older adults may have reduced sensation and slower reaction times. Lower water heater settings prevent scald injuries. Working smoke and carbon monoxide detectors are essential.','Safety & Infection Control','Fundamentals'),
('Set17-RN-15','Safety and Infection Control','Workplace violence','single_best_answer','Safety and Infection Control • Workplace violence • Multiple choice A visitor in the hallway becomes enraged and pulls out a knife. What should the nurse do first?','Try to take the knife away|Move away to a safe location, keep others away, and call security or activate the facility''s emergency code|Argue with the visitor to calm them|Continue with client care','B','Staff safety comes first. The nurse leaves the area, alerts others, and activates the emergency response. Nurses do not attempt to disarm someone.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-16','Safety and Infection Control','Multidrug-resistant organisms','single_best_answer','Safety and Infection Control • Multidrug-resistant organisms • Multiple choice A client is colonized with Candida auris. Which action is most important to prevent its spread?','Standard precautions only|Contact precautions and cleaning with a disinfectant proven effective against C. auris|Droplet precautions only|No special precautions are needed for colonization    ','B','C. auris is a multidrug-resistant fungus that persists on surfaces and spreads in healthcare settings. Contact precautions and effective disinfectants (such as those on EPA List P) are required, even for colonized clients.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-17','Safety and Infection Control','Healthcare worker immunization','single_best_answer','Safety and Infection Control • Healthcare worker immunization • Multiple choice A newly hired nurse asks why hepatitis B vaccination is recommended. What is the best response?','"It protects against hepatitis A and C."|"It protects against a bloodborne infection you could be exposed to through needlesticks or splashes, and a titer can confirm immunity."|"It is only needed for surgical staff."|"It replaces the need for standard precautions."','B','Healthcare workers with potential blood exposure should complete the hepatitis B series and have post-vaccination antibody testing. Vaccination does not replace standard precautions.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-18','Safety and Infection Control','Elopement','single_best_answer','Safety and Infection Control • Elopement • Multiple choice A client with dementia cannot be found on the unit during the 1400 rounds. What should the nurse do first?','Wait 1 hour to see if the client returns|Immediately notify the charge nurse and initiate the facility''s missing-client code and search|Call the family and ask if the client went home|Document the absence in the chart','B','A missing client with cognitive impairment is an emergency with a high risk of harm. The facility''s search protocol is activated immediately.','Safety & Infection Control','Safety & Infection Control'),
('Set17-RN-19','Safety and Infection Control','Bar-code medication administration','single_best_answer','Safety and Infection Control • Bar-code medication administration • Multiple choice When the nurse scans a client''s medication, the bar-code system displays a "wrong patient" alert. What should the nurse do?','Override the alert and give the medication|Stop, do not give the medication, and investigate the discrepancy|Scan the medication again until the alert clears|Give the medication and report the alert later  ','B','Bar-code alerts are safety checks. Workarounds and overrides without investigation cause medication errors. The nurse verifies the client, order, and medication before proceeding.','Safety & Infection Control','Safety & Infection Control'),
('Set18-RN-1','Management of Care','Prioritization: sensory','single_best_answer','Management of Care • Prioritization: sensory • Multiple choice The nurse in an eye and ear clinic receives four telephone messages. Which client should the nurse call back first?','A client who reports sudden flashes of light, new floaters, and a "curtain" coming down over the vision in one eye|A client 1 day after cataract surgery who reports mild scratchiness|A client whose hearing aid is whistling|A client with Ménière''s disease requesting a refill of meclizine','A','Flashes, floaters, and a curtain-like shadow indicate retinal detachment, which requires emergency treatment to preserve vision. Mild scratchiness after cataract surgery is expected.','Integrated','Management of Care'),
('Set18-RN-2','Pharmacological and Parenteral Therapies','Acute angle-closure glaucoma','single_best_answer','Pharmacological and Parenteral Therapies • Acute angle-closure glaucoma • Multiple choice A client arrives with sudden severe eye pain, blurred vision with halos around lights, nausea, and a firm, reddened eye. Which prescription should the nurse question?','Timolol ophthalmic drops|Acetazolamide IV|Atropine ophthalmic drops|Pilocarpine ophthalmic drops','C','These findings suggest acute angle-closure glaucoma. Atropine dilates the pupil, which can further block aqueous outflow and raise intraocular pressure. The other drugs lower intraocular pressure.','Integrated','Pharmacology'),
('Set18-RN-3','Reduction of Risk Potential','Cataract surgery','single_best_answer','Reduction of Risk Potential • Cataract surgery • Multiple choice The nurse is providing discharge teaching after cataract surgery. Which client statement indicates a need for further teaching?','"I''ll wear the eye shield at night."|"I''ll bend over at the waist to tie my shoes."|"I''ll call if I have sudden eye pain or decreased vision."|"I''ll avoid lifting anything heavy for now."','B','Bending at the waist, straining, and heavy lifting raise intraocular pressure. The client should bend at the knees or use slip-on shoes. Sudden pain or vision loss may indicate hemorrhage, infection, or increased pressure.','Integrated','Adult Health'),
('Set18-RN-4','Health Promotion and Maintenance','Ménière''s disease','single_best_answer','Health Promotion and Maintenance • Ménière''s disease • Multiple choice The nurse is teaching a client with Ménière''s disease. Which instruction is appropriate?','"Follow a high-sodium diet to maintain fluid balance."|"During a vertigo attack, lie still in a safe position and keep your eyes fixed on a stationary object."|"Increase caffeine intake to improve alertness."|"Drive as usual during attacks."    ','B','Lying still reduces vertigo and prevents falls. Limiting sodium, caffeine, and alcohol can reduce endolymphatic fluid and the frequency of attacks. Driving is unsafe during episodes.','Integrated','Fundamentals'),
('Set18-RN-5','Physiological Adaptation','Acute pericarditis','single_best_answer','Physiological Adaptation • Acute pericarditis • Multiple choice A client reports sharp chest pain that worsens when lying down and when taking a deep breath. The pain improves when sitting up and leaning forward. Which additional finding does the nurse expect?','A pericardial friction rub|An S4 heart sound only|Unilateral leg swelling|Tearing back pain radiating to the abdomen','A','Acute pericarditis causes positional, pleuritic chest pain and a scratchy friction rub, often with diffuse ST elevation. Treatment typically includes NSAIDs and colchicine.','Integrated','Adult Health'),
('Set18-RN-6','Physiological Adaptation','Aortic stenosis','single_best_answer','Physiological Adaptation • Aortic stenosis • Multiple choice A client with known severe aortic stenosis is being followed in a cardiology clinic. Which symptom should the nurse instruct the client to report immediately?','Occasional mild fatigue in the evening|Fainting or near-fainting during exertion|Increased appetite|A mild seasonal cough','B','Exertional syncope, angina, and heart failure symptoms in aortic stenosis indicate severe obstruction and poor prognosis without valve replacement.','Integrated','Adult Health'),
('Set18-RN-7','Health Promotion and Maintenance','Raynaud''s phenomenon','single_best_answer','Health Promotion and Maintenance • Raynaud''s phenomenon • Multiple choice A client with Raynaud''s phenomenon asks how to prevent attacks. Which instruction should the nurse give?','"Hold ice packs to toughen your fingers."|"Keep your hands and body warm, wear gloves in cold places, and avoid smoking."|"Drink more caffeine."|"Soak your fingers in cold water daily."','B','Cold exposure, stress, smoking, and caffeine trigger vasospasm. Staying warm, including the body core, and wearing gloves (even when handling cold items from the freezer) prevent attacks.','Integrated','Fundamentals'),
('Set18-RN-8','Reduction of Risk Potential','Pneumonectomy','single_best_answer','Reduction of Risk Potential • Pneumonectomy • Multiple choice A client is 1 day postoperative after a right pneumonectomy. How should the nurse position the client?','Completely on the left side|Supine or partially turned onto the right (operative) side, as prescribed|Prone|Trendelenburg    ','B','After pneumonectomy, lying on the operative side or back allows the remaining lung to expand fully and helps prevent mediastinal shift. Complete side-lying on the nonoperative side is usually avoided.','Integrated','Adult Health'),
('Set18-RN-9','Health Promotion and Maintenance','Obstructive sleep apnea','single_best_answer','Health Promotion and Maintenance • Obstructive sleep apnea • Multiple choice A client with obstructive sleep apnea is prescribed CPAP. Which statement indicates understanding?','"I''ll use CPAP only when I feel tired."|"I''ll wear the CPAP every night, including during naps, and clean the mask and tubing regularly."|"I''ll take a sleeping pill so I can tolerate the mask."|"CPAP will cure my sleep apnea in a few weeks."','B','CPAP keeps the airway open only while it is worn, so consistent nightly use is needed. Sedatives worsen airway collapse. Weight loss and avoiding alcohol before bed also help.','Integrated','Fundamentals'),
('Set18-RN-10','Pharmacological and Parenteral Therapies','Antivirals for influenza','single_best_answer','Pharmacological and Parenteral Therapies • Antivirals for influenza • Multiple choice A client with confirmed influenza asks about oseltamivir. What is the nurse''s best response?','"It is most effective when started within 48 hours of symptom onset."|"It cures influenza within 24 hours."|"It replaces the need for a yearly flu vaccine."|"It works only if started after a week of symptoms."','A','Neuraminidase inhibitors shorten illness and reduce complications when started early, ideally within 48 hours. High-risk and hospitalized clients may benefit even later. It does not replace vaccination.','Integrated','Pharmacology'),
('Set18-RN-11','Basic Care and Comfort','Trigeminal neuralgia','single_best_answer','Basic Care and Comfort • Trigeminal neuralgia • Multiple choice A client with trigeminal neuralgia has severe facial pain triggered by eating. Which intervention is most appropriate?','Serve very hot foods to relax the muscles|Offer lukewarm, soft foods and encourage chewing on the unaffected side|Encourage vigorous brushing of the teeth|Apply an ice pack to the face before meals','B','Temperature extremes, chewing, and touch can trigger attacks. Soft, lukewarm foods and chewing on the unaffected side reduce triggers. Carbamazepine is commonly prescribed.','Integrated','Adult Health'),
('Set18-RN-12','Physiological Adaptation','Amyotrophic lateral sclerosis','single_best_answer','Physiological Adaptation • Amyotrophic lateral sclerosis • Multiple choice A client with advanced amyotrophic lateral sclerosis (ALS) has increasing difficulty swallowing and a weak cough. Which is the nurse''s priority concern?','Impaired verbal communication|Aspiration and respiratory compromise|Disturbed body image|Constipation    ','B','ALS progressively weakens bulbar and respiratory muscles, increasing the risk of aspiration pneumonia and respiratory failure. These are the leading causes of death. Cognition is often preserved.','Integrated','Adult Health'),
('Set18-RN-13','Health Promotion and Maintenance','Genetic counseling','single_best_answer','Health Promotion and Maintenance • Genetic counseling • Multiple choice A client whose father has Huntington''s disease asks about the chance of inheriting it. Which response by the nurse is accurate?','"There is no genetic risk."|"It is inherited in an autosomal dominant pattern, so each child of an affected parent has a 50% chance of inheriting the gene."|"Only sons can inherit it."|"The chance is 25%."','B','Huntington''s disease is autosomal dominant. Genetic counseling is recommended before and after testing because of the significant psychological and family implications.','Integrated','Fundamentals'),
('Set18-RN-14','Safety and Infection Control','Immune thrombocytopenia','single_best_answer','Safety and Infection Control • Immune thrombocytopenia • Multiple choice A client with immune thrombocytopenia (ITP) has a platelet count of 22,000/mm³. Which instruction should the nurse include?','"Take ibuprofen for headaches."|"Avoid aspirin and NSAIDs, use a soft toothbrush, and report any bleeding."|"Take up contact sports to strengthen your body."|"Floss vigorously twice a day."','B','In ITP, autoantibodies destroy platelets. Avoiding antiplatelet drugs and trauma reduces bleeding risk. Corticosteroids are often the first-line treatment.','Integrated','Safety & Infection Control'),
('Set18-RN-15','Physiological Adaptation','Polycythemia vera','single_best_answer','Physiological Adaptation • Polycythemia vera • Multiple choice A client with polycythemia vera has a hematocrit of 58%. Which complication is the nurse most concerned about?','Hypotension from anemia|Thrombosis such as stroke, MI, or DVT|Hypoglycemia|Hyperkalemia only','B','Excess red cells increase blood viscosity and the risk of clotting. Treatment includes therapeutic phlebotomy, hydration, and low-dose aspirin as prescribed. Itching after warm baths is a common symptom.','Integrated','Adult Health'),
('Set18-RN-16','Reduction of Risk Potential','Ileal conduit','single_best_answer','Reduction of Risk Potential • Ileal conduit • Multiple choice A client has an ileal conduit after cystectomy for bladder cancer. Which finding should the nurse report?','Continuous flow of urine into the pouch|Mucus threads in the urine|A dark purple stoma|A moist, pink stoma    ','C','A dusky or dark stoma indicates impaired blood flow. Continuous urine flow and mucus (from the intestinal segment) are expected with an ileal conduit.','Integrated','Adult Health'),
('Set18-RN-17','Health Promotion and Maintenance','Testicular self-examination','single_best_answer','Health Promotion and Maintenance • Testicular self-examination • Multiple choice The nurse is teaching a 20-year-old male about testicular self-examination. Which instruction is correct?','"Perform the exam once a year."|"Examine each testicle monthly, ideally after a warm shower, and report any lump, swelling, or heaviness."|"Only examine if you have pain."|"Squeeze the testicles firmly to check for pain."','B','Testicular cancer is most common in young men. Warmth relaxes the scrotum, making it easier to feel changes. Most cancers present as a painless lump.','Integrated','Fundamentals'),
('Set18-RN-18','Safety and Infection Control','Sexually transmitted infections','single_best_answer','Safety and Infection Control • Sexually transmitted infections • Multiple choice A client is treated for chlamydia with a single dose of azithromycin. Which instruction should the nurse include?','"You can resume sexual activity tonight."|"Avoid sexual activity for 7 days after treatment and until your partners are treated, and consider retesting in about 3 months."|"Your partners don''t need treatment."|"You''ll be immune to chlamydia now."','B','Abstaining for 7 days and until partners are treated prevents reinfection. Retesting in about 3 months is recommended because reinfection is common. Doxycycline is now the preferred first-line treatment in most cases.','Integrated','Safety & Infection Control'),
('Set18-RN-19','Physiological Adaptation','Stimulant intoxication','single_best_answer','Physiological Adaptation • Stimulant intoxication • Multiple choice A client is brought to the emergency department after using cocaine. Which findings does the nurse expect?','Pinpoint pupils, bradycardia, and hypothermia|Dilated pupils, tachycardia, hypertension, hyperthermia, and agitation|Slow, shallow respirations and sedation|Hypotension and constricted pupils  ','B','Cocaine causes sympathetic stimulation, which can lead to chest pain, MI, dysrhythmias, stroke, and seizures. Benzodiazepines are commonly used to control agitation and sympathetic effects.','Integrated','Adult Health'),
('Set19-RN-1','Management of Care','Prioritization: urology','single_best_answer','Management of Care • Prioritization: urology • Multiple choice The nurse on a urology unit receives report on four clients. Which client should the nurse assess first?','A client with a nephrostomy tube that has had no drainage for 2 hours who reports new severe flank pain|A client 4 hours after shock wave lithotripsy with pink-tinged urine|A client with polycystic kidney disease requesting a BP medication refill|A client with benign prostatic hyperplasia who reports nocturia','A','Absent nephrostomy drainage with new flank pain suggests obstruction or dislodgement, which can cause hydronephrosis and kidney damage. Mild hematuria after lithotripsy is expected.','Integrated','Management of Care'),
('Set19-RN-2','Reduction of Risk Potential','Elective cardioversion','single_best_answer','Reduction of Risk Potential • Elective cardioversion • Multiple choice A client with atrial fibrillation of about 1 week''s duration is scheduled for elective synchronized cardioversion. Which finding is most important for the nurse to verify before the procedure?','The client ate a light breakfast|The client has received adequate anticoagulation or had a transesophageal echocardiogram to rule out atrial thrombus|The client took their digoxin this morning|The client''s potassium is 3.1 mEq/L','B','Atrial fibrillation lasting more than 48 hours can form atrial clots that may embolize when sinus rhythm is restored. Adequate anticoagulation or a TEE is required. The client should also be NPO, and potassium should be normal.','Integrated','Adult Health'),
('Set19-RN-3','Health Promotion and Maintenance','Implantable cardioverter-defibrillator','single_best_answer','Health Promotion and Maintenance • Implantable cardioverter-defibrillator • Multiple choice The nurse is teaching a client with a new implantable cardioverter-defibrillator (ICD). Which instruction is correct?','"If the device shocks you once and you feel fine afterward, contact your cardiology provider. If you receive multiple shocks or feel unwell, call 911."|"Ignore shocks unless you have more than five in a day."|"Avoid all physical activity for life."|"Family members will be seriously injured if they touch you during a shock."','A','A single shock with no symptoms should be reported. Repeated shocks or symptoms such as chest pain or fainting require emergency care. A person touching the client may feel a tingle but will not be harmed.','Integrated','Fundamentals'),
('Set19-RN-4','Reduction of Risk Potential','Tracheostomy cuff pressure','single_best_answer','Reduction of Risk Potential • Tracheostomy cuff pressure • Multiple choice The nurse is checking the cuff pressure of a client''s cuffed tracheostomy tube. Which range is generally recommended?','5–10 cm H2O|20–30 cm H2O|40–50 cm H2O|60–70 cm H2O    ','B','A cuff pressure of about 20–30 cm H2O seals the airway to reduce aspiration without compressing tracheal capillaries. Excessive pressure can cause tracheal ischemia and stenosis.','Integrated','Adult Health'),
('Set19-RN-5','Pharmacological and Parenteral Therapies','Cluster headache','single_best_answer','Pharmacological and Parenteral Therapies • Cluster headache • Multiple choice A client arrives with severe, one-sided pain around the eye, tearing, and nasal congestion that began 15 minutes ago. The client has a history of cluster headaches. Which treatment does the nurse anticipate first?','100% oxygen at 12–15 L/min by nonrebreather mask|Oral ibuprofen|A warm compress to the eye|IV fluids only','A','High-flow oxygen is a first-line abortive therapy for cluster headaches and often relieves pain within about 15 minutes. Subcutaneous or intranasal triptans are also used.','Integrated','Pharmacology'),
('Set19-RN-6','Physiological Adaptation','Primary hyperaldosteronism','single_best_answer','Physiological Adaptation • Primary hyperaldosteronism • Multiple choice A client with resistant hypertension is being evaluated for primary hyperaldosteronism. Which lab finding supports this diagnosis?','Hyperkalemia|Hypokalemia|Hypoglycemia|Hypercalcemia','B','Excess aldosterone causes sodium and water retention (hypertension) and potassium excretion (hypokalemia). Treatment may include surgery or an aldosterone antagonist such as spironolactone.','Integrated','Adult Health'),
('Set19-RN-7','Pharmacological and Parenteral Therapies','SGLT2 inhibitors','single_best_answer','Pharmacological and Parenteral Therapies • SGLT2 inhibitors • Multiple choice A client with type 2 diabetes takes empagliflozin and is scheduled for elective surgery. Which information should the nurse include?','"Take a double dose the morning of surgery."|"This medication is usually stopped several days before surgery because it can cause ketoacidosis even with near-normal glucose levels."|"It lowers blood sugar by increasing insulin release."|"It prevents urinary tract infections."','B','SGLT2 inhibitors can cause euglycemic DKA, especially during fasting, surgery, or illness, so they are typically held about 3 days before surgery. They increase glucose excretion in the urine, which raises the risk of genital yeast infections.','Integrated','Pharmacology'),
('Set19-RN-8','Reduction of Risk Potential','Insulin pump','single_best_answer','Reduction of Risk Potential • Insulin pump • Multiple choice A client with an insulin pump notices the infusion tubing was disconnected for several hours overnight. Why is the nurse most concerned?','Pumps use long-acting insulin, so glucose will drop|Pumps deliver only rapid-acting insulin, so the client can develop hyperglycemia and ketoacidosis quickly|Disconnection has no effect|The client will develop hypoglycemia    ','B','Because pumps contain only rapid- or short-acting insulin, there is no long-acting insulin reserve. Interruption can lead to DKA within hours. Clients check glucose and ketones and have a backup plan.','Integrated','Adult Health'),
('Set19-RN-9','Health Promotion and Maintenance','Hepatitis C','single_best_answer','Health Promotion and Maintenance • Hepatitis C • Multiple choice A client newly diagnosed with chronic hepatitis C asks about treatment. Which response by the nurse is accurate?','"There is no effective treatment."|"Direct-acting antiviral medications taken for 8–12 weeks cure most people."|"A vaccine will cure the infection."|"Treatment is only for people with liver failure."','B','Direct-acting antivirals cure more than 95% of hepatitis C infections. There is no vaccine for hepatitis C. Clients should avoid alcohol and be vaccinated against hepatitis A and B.','Integrated','Fundamentals'),
('Set19-RN-10','Reduction of Risk Potential','Colonoscopy preparation','single_best_answer','Reduction of Risk Potential • Colonoscopy preparation • Multiple choice An 80-year-old client is completing a bowel preparation for colonoscopy. Which finding is most important for the nurse to report?','Frequent watery stools|Dizziness when standing, dry mouth, and decreased urine output|Clear yellow liquid stools|Mild abdominal fullness','B','Bowel preparation can cause dehydration and electrolyte imbalances, especially in older adults. Watery, clear stools indicate an effective prep. Red and purple liquids are avoided because they can look like blood.','Integrated','Adult Health'),
('Set19-RN-11','Physiological Adaptation','Small bowel obstruction','single_best_answer','Physiological Adaptation • Small bowel obstruction • Multiple choice Which findings does the nurse expect in a client with an early mechanical small bowel obstruction?','Absent bowel sounds and a rigid abdomen|Colicky abdominal pain, vomiting, distention, and high-pitched bowel sounds|Diarrhea with blood|Left lower quadrant pain relieved by defecation','B','Early obstruction causes cramping pain, vomiting, and high-pitched bowel sounds as the bowel works against the blockage. Later, bowel sounds may become absent. Treatment includes NG decompression, IV fluids, and electrolyte correction.','Integrated','Adult Health'),
('Set19-RN-12','Safety and Infection Control','G6PD deficiency','single_best_answer','Safety and Infection Control • G6PD deficiency • Multiple choice A client with glucose-6-phosphate dehydrogenase (G6PD) deficiency asks what to avoid. Which items should the nurse include?','Dairy products|Fava beans and certain drugs such as sulfonamides and primaquine|All fruits|Acetaminophen at any dose','B','Oxidative stress from fava beans, certain medications, and infections can trigger hemolytic anemia in G6PD deficiency.','Integrated','Safety & Infection Control'),
('Set19-RN-13','Physiological Adaptation','Aplastic anemia','single_best_answer','Physiological Adaptation • Aplastic anemia • Multiple choice Which lab pattern does the nurse expect in a client with aplastic anemia?','Elevated WBC, normal hemoglobin, and elevated platelets|Low WBC, low hemoglobin, and low platelets (pancytopenia)|Isolated low platelets|Elevated hemoglobin    ','B','Aplastic anemia is bone marrow failure affecting all cell lines. Care includes infection and bleeding precautions, transfusions, immunosuppression, or stem cell transplant.','Integrated','Adult Health'),
('Set19-RN-14','Health Promotion and Maintenance','Total laryngectomy','single_best_answer','Health Promotion and Maintenance • Total laryngectomy • Multiple choice A client is being discharged after a total laryngectomy. Which instruction should the nurse include?','"You''ll be able to speak normally in a few days."|"Protect your stoma with a shower shield, use humidification, and avoid swimming."|"Keep the stoma tightly covered with plastic wrap."|"You can still breathe through your nose and mouth."','B','After total laryngectomy, the client breathes only through the neck stoma. Water entering the stoma can go directly into the lungs. Humidification replaces the nose''s warming and moistening function. Speech options include an electrolarynx or a tracheoesophageal prosthesis.','Integrated','Fundamentals'),
('Set19-RN-15','Physiological Adaptation','HELLP syndrome','single_best_answer','Physiological Adaptation • HELLP syndrome • Multiple choice A client at 34 weeks'' gestation with preeclampsia reports right upper quadrant pain and nausea. Which lab findings suggest HELLP syndrome?','Elevated platelets and low liver enzymes|Hemolysis, elevated liver enzymes, and low platelets|Low hemoglobin with normal liver enzymes only|Elevated glucose and ketones','B','HELLP stands for Hemolysis, Elevated Liver enzymes, and Low Platelets. It is a severe form of preeclampsia that can cause liver rupture, DIC, and death, and delivery is the definitive treatment.','Integrated','Adult Health'),
('Set19-RN-16','Physiological Adaptation','Shoulder dystocia','single_best_answer','Physiological Adaptation • Shoulder dystocia • Multiple choice During delivery, the fetal head emerges and then retracts against the perineum ("turtle sign"). Which action should the nurse take?','Apply fundal pressure|Assist with the McRoberts maneuver (sharply flexing the client''s thighs onto the abdomen) and apply suprapubic pressure as directed|Push the fetal head back into the vagina|Place the client in Trendelenburg position','B','McRoberts positioning and suprapubic pressure help dislodge the anterior shoulder. Fundal pressure worsens impaction and increases the risk of uterine rupture and brachial plexus injury.','Integrated','Adult Health'),
('Set19-RN-17','Health Promotion and Maintenance','Gestational trophoblastic disease','single_best_answer','Health Promotion and Maintenance • Gestational trophoblastic disease • Multiple choice A client had a suction evacuation for a hydatidiform mole. Which statement indicates understanding of follow-up care?','"I can try to get pregnant again right away."|"I''ll have regular hCG blood tests and use reliable contraception during the follow-up period."|"I don''t need any follow-up."|"A rising hCG level is a good sign."    ','B','Serial hCG levels are monitored until normal to detect persistent disease or choriocarcinoma. Pregnancy would raise hCG and interfere with monitoring, so reliable contraception is needed.','Integrated','Fundamentals'),
('Set19-RN-18','Pharmacological and Parenteral Therapies','Buprenorphine induction','single_best_answer','Pharmacological and Parenteral Therapies • Buprenorphine induction • Multiple choice A client with opioid use disorder is starting buprenorphine. Which timing is most important for the first dose?','Immediately after the last opioid use|When the client shows objective signs of moderate withdrawal (for example, by the Clinical Opiate Withdrawal Scale)|Only after 2 weeks of abstinence|At the same time as a full-agonist opioid','B','Buprenorphine is a partial agonist with high receptor affinity. Given too early, it displaces full agonists and precipitates withdrawal. Waiting for moderate withdrawal prevents this.','Integrated','Pharmacology'),
('Set19-RN-19','Pharmacological and Parenteral Therapies','Tricyclic antidepressant overdose','single_best_answer','Pharmacological and Parenteral Therapies • Tricyclic antidepressant overdose • Multiple choice A client is admitted after an overdose of amitriptyline. The ECG shows a widening QRS complex. Which medication does the nurse anticipate?','Sodium bicarbonate IV|Flumazenil|Physostigmine as first-line|Naloxone  ','A','Tricyclic toxicity blocks sodium channels, causing QRS widening, dysrhythmias, seizures, and hypotension. Sodium bicarbonate counteracts the sodium channel blockade. Anticholinergic effects are also common.','Integrated','Pharmacology'),
('Set20-RN-1','Management of Care','Prioritization: emergency department','single_best_answer','Management of Care • Prioritization: emergency department • Multiple choice The emergency department nurse is assigned four new clients. Which client should the nurse assess first?','A client with new-onset atrial fibrillation, HR 152/min, BP 78/40 mm Hg, and chest pain|A client with a laceration on the forearm with controlled bleeding|A client with a sprained ankle rating pain 6/10|A client with a urinary tract infection and a temperature of 100.4°F (38°C)','A','Rapid atrial fibrillation with hypotension and chest pain indicates hemodynamic instability, which requires immediate intervention. The other clients are stable.','Integrated','Management of Care'),
('Set20-RN-2','Physiological Adaptation','Unstable tachycardia','single_best_answer','Physiological Adaptation • Unstable tachycardia • Multiple choice A client with supraventricular tachycardia at 190/min becomes confused, with BP 76/42 mm Hg. Vagal maneuvers and adenosine have not been attempted. Which intervention does the nurse anticipate first?','Oral metoprolol|Synchronized cardioversion|Unsynchronized defibrillation|Observation for 30 minutes','B','Tachycardia with signs of instability (hypotension, altered mental status) and a pulse is treated with synchronized cardioversion. Synchronization avoids delivering a shock during the vulnerable T wave. Defibrillation is for pulseless rhythms such as VF.','Integrated','Adult Health'),
('Set20-RN-3','Physiological Adaptation','Asystole','single_best_answer','Physiological Adaptation • Asystole • Multiple choice A client in cardiac arrest has asystole on the monitor, confirmed in two leads. Which action is appropriate?','Deliver a defibrillation shock immediately|Continue high-quality CPR and administer epinephrine as prescribed|Perform synchronized cardioversion|Administer adenosine','B','Asystole is not a shockable rhythm. Management is CPR, epinephrine every 3–5 minutes, and identifying reversible causes (the H''s and T''s).','Integrated','Adult Health'),
('Set20-RN-4','Physiological Adaptation','Heart transplant','single_best_answer','Physiological Adaptation • Heart transplant • Multiple choice The nurse is teaching a client who had a heart transplant 2 months ago. Which statement indicates understanding?','"My heart rate will increase immediately when I start exercising."|"I''ll warm up gradually before exercise and cool down slowly, because my new heart takes longer to respond."|"I won''t need any more heart biopsies."|"I can stop my immunosuppressants once I feel well."    ','B','The transplanted heart is denervated, so heart rate increases slowly in response to circulating catecholamines rather than nerve signals. Prolonged warm-up and cool-down periods are needed. Endomyocardial biopsies monitor for rejection, and immunosuppression is lifelong.','Integrated','Adult Health'),
('Set20-RN-5','Reduction of Risk Potential','Peripheral bypass graft','single_best_answer','Reduction of Risk Potential • Peripheral bypass graft • Multiple choice A client is 8 hours postoperative after a femoral-popliteal bypass graft. Which finding requires immediate action?','Incisional pain rated 4/10|Pedal pulse present by Doppler but weaker than 1 hour ago, with a cooler foot|Mild swelling of the operative leg|Serosanguineous drainage on the dressing','B','A diminishing pulse and cooler extremity suggest graft occlusion, which requires emergency intervention. Mild edema is common after revascularization as blood flow returns.','Integrated','Adult Health'),
('Set20-RN-6','Reduction of Risk Potential','Chest tube removal','single_best_answer','Reduction of Risk Potential • Chest tube removal • Multiple choice The nurse is assisting with chest tube removal. What should the nurse instruct the client to do as the tube is pulled?','Breathe in and out rapidly|Take a deep breath and hold it or bear down (Valsalva), as directed by the provider|Cough forcefully|Lie flat and relax completely','B','Holding the breath or performing a Valsalva maneuver increases intrathoracic pressure and prevents air from entering the pleural space during removal. An occlusive dressing is applied immediately, and a chest x-ray may follow.','Integrated','Adult Health'),
('Set20-RN-7','Reduction of Risk Potential','Pulse oximetry accuracy','single_best_answer','Reduction of Risk Potential • Pulse oximetry accuracy • Multiple choice Which situation is most likely to cause a falsely high pulse oximetry reading?','Warm fingers with good perfusion|Carbon monoxide poisoning|Clean, unpolished fingernails|A client at rest','B','Standard oximeters read carboxyhemoglobin as oxyhemoglobin, overestimating saturation. Poor perfusion, cold extremities, motion, and dark nail polish usually cause inaccurate or low readings. Oximeters may also overestimate saturation in clients with darker skin.','Integrated','Adult Health'),
('Set20-RN-8','Management of Care','Organ donation','single_best_answer','Management of Care • Organ donation • Multiple choice A client with a severe brain injury is being evaluated for brain death. Which action by the nurse is correct regarding organ donation?','Ask the family about organ donation before the evaluation is complete|Notify the organ procurement organization according to hospital policy and allow its trained staff to approach the family|Decide that the client is not a candidate because of age|Wait until after the ventilator is removed to discuss donation    ','B','Federal regulations require timely referral of imminent deaths to the organ procurement organization. Trained requesters approach families, which respects the family and improves consent rates.','Integrated','Management of Care'),
('Set20-RN-9','Health Promotion and Maintenance','Transient ischemic attack','single_best_answer','Health Promotion and Maintenance • Transient ischemic attack • Multiple choice A client had 20 minutes of right arm weakness and slurred speech yesterday, which resolved completely. Which statement by the nurse is most accurate?','"Since the symptoms went away, no follow-up is needed."|"This may have been a transient ischemic attack, which is a warning sign for stroke and needs urgent evaluation."|"This was probably anxiety."|"You should wait for it to happen again before seeing a provider."','B','TIAs signal a high short-term risk of stroke. Urgent evaluation (imaging, carotid studies, cardiac monitoring) and prevention measures, such as antiplatelet therapy and risk factor control, are needed.','Integrated','Fundamentals'),
('Set20-RN-10','Pharmacological and Parenteral Therapies','Hypoparathyroidism','single_best_answer','Pharmacological and Parenteral Therapies • Hypoparathyroidism • Multiple choice A client develops permanent hypoparathyroidism after neck surgery. Which long-term treatment does the nurse anticipate?','Potassium supplements|Calcium supplements and active vitamin D (calcitriol)|Levothyroxine only|A low-calcium diet','B','Without parathyroid hormone, calcium levels fall. Oral calcium and activated vitamin D maintain calcium levels. The client is taught to recognize tingling and muscle cramps, which suggest hypocalcemia.','Integrated','Pharmacology'),
('Set20-RN-11','Pharmacological and Parenteral Therapies','Adrenalectomy','single_best_answer','Pharmacological and Parenteral Therapies • Adrenalectomy • Multiple choice A client is recovering from a bilateral adrenalectomy for Cushing''s syndrome. Which medication will the client need long term?','Insulin|Glucocorticoid and mineralocorticoid replacement|Levothyroxine|Potassium chloride only','B','Removing both adrenal glands eliminates cortisol and aldosterone production. Lifelong hydrocortisone and fludrocortisone replacement is needed, with stress dosing during illness.','Integrated','Pharmacology'),
('Set20-RN-12','Reduction of Risk Potential','Air embolism','single_best_answer','Reduction of Risk Potential • Air embolism • Multiple choice While a central venous catheter is being changed, a client suddenly becomes short of breath, has chest pain, and becomes hypotensive. The nurse suspects an air embolism. What should the nurse do first?','Place the client in high-Fowler''s position|Clamp the catheter and place the client on the left side in Trendelenburg position|Flush the catheter with saline|Remove the catheter completely    ','B','Clamping stops more air from entering. Left lateral Trendelenburg positioning traps air in the right atrium away from the pulmonary outflow tract. The nurse then gives oxygen and notifies the provider.','Integrated','Adult Health'),
('Set20-RN-13','Reduction of Risk Potential','Kidney biopsy','single_best_answer','Reduction of Risk Potential • Kidney biopsy • Multiple choice A client returns from a percutaneous kidney biopsy. Which finding should the nurse report immediately?','Mild soreness at the site|Gross hematuria with clots, flank pain, and a falling BP|Slightly pink urine on the first void|The client asks for food','B','Bleeding is the major complication after kidney biopsy. Gross hematuria with clots, increasing flank pain, and hypotension suggest hemorrhage. Bed rest and frequent vital signs are standard after the procedure.','Integrated','Adult Health'),
('Set20-RN-14','Physiological Adaptation','Malignant spinal cord compression','single_best_answer','Physiological Adaptation • Malignant spinal cord compression • Multiple choice A client with metastatic prostate cancer reports worsening back pain for a week and new leg weakness. What should the nurse do?','Give a PRN analgesic and reassess tomorrow|Report the findings immediately because they suggest spinal cord compression, an oncologic emergency|Encourage the client to walk more|Apply heat to the back','B','New or worsening back pain with neurological deficits in a client with cancer suggests metastatic spinal cord compression. Prompt corticosteroids, imaging, and radiation or surgery are needed to preserve function.','Integrated','Adult Health'),
('Set20-RN-15','Safety and Infection Control','Oral chemotherapy at home','single_best_answer','Safety and Infection Control • Oral chemotherapy at home • Multiple choice A client is starting oral capecitabine at home. Which instruction should the nurse include?','"Crush the tablets if they''re hard to swallow."|"Handle the tablets carefully, wash your hands after taking them, and caregivers should wear gloves if they handle them."|"Store the tablets in a shared pill organizer with your spouse''s medicines."|"Double the next dose if you miss one."','B','Oral chemotherapy is hazardous. Safe handling protects the client and family. Tablets are not crushed, missed doses are not doubled, and hand-foot syndrome and diarrhea are reported.','Integrated','Safety & Infection Control'),
('Set20-RN-16','Physiological Adaptation','Graft-versus-host disease','single_best_answer','Physiological Adaptation • Graft-versus-host disease • Multiple choice A client received an allogeneic stem cell transplant 4 weeks ago. Which findings suggest acute graft-versus-host disease?','Rash on the palms and soles, diarrhea, and elevated bilirubin|Bradycardia and hypothermia|Hyperglycemia only|Clear lungs and normal stools    ','A','Donor immune cells attack host tissues, most often the skin, GI tract, and liver. GVHD is managed with immunosuppression.','Integrated','Adult Health'),
('Set20-RN-17','Physiological Adaptation','Hyperemesis gravidarum','single_best_answer','Physiological Adaptation • Hyperemesis gravidarum • Multiple choice A client at 10 weeks'' gestation has persistent vomiting, a 6% weight loss, and ketones in the urine. Which treatment does the nurse anticipate?','Encourage three large meals a day|IV fluids with electrolyte replacement, thiamine, and antiemetics as prescribed|Discharge with no treatment|A high-fat diet','B','Hyperemesis gravidarum causes dehydration, electrolyte imbalance, and ketosis. Thiamine prevents Wernicke encephalopathy, especially before dextrose is given.','Integrated','Adult Health'),
('Set20-RN-18','Physiological Adaptation','Uterine rupture','single_best_answer','Physiological Adaptation • Uterine rupture • Multiple choice A client attempting a vaginal birth after a previous cesarean suddenly reports severe abdominal pain. The fetal heart rate drops to 70/min, and the presenting part is no longer palpable on vaginal exam. What does the nurse suspect?','Normal second-stage labor|Uterine rupture|Placenta previa|Cord prolapse','B','Sudden pain, fetal bradycardia, and loss of fetal station suggest uterine rupture, an obstetric emergency requiring immediate cesarean delivery. Uterine scar is the main risk factor.','Integrated','Adult Health'),
('Set20-RN-19','Physiological Adaptation','Pediatric DKA','single_best_answer','Physiological Adaptation • Pediatric DKA • Multiple choice A 10-year-old is being treated for DKA. After 6 hours of therapy, the child reports a severe headache, becomes confused, and has a slowing heart rate. What does the nurse suspect?','Hypoglycemia|Cerebral edema|Expected fatigue|Hyperkalemia only  ','B','Cerebral edema is the most serious complication of pediatric DKA treatment, often linked to rapid shifts in osmolality. It typically presents 4–12 hours into therapy. Treatment includes reducing the fluid rate, raising the head of the bed, and giving mannitol or hypertonic saline.','Integrated','Adult Health'),
('Set21-RN-1','Management of Care','Prioritization: postoperative','single_best_answer','Management of Care • Prioritization: postoperative • Multiple choice The nurse receives report on four postoperative clients. Which client should the nurse assess first?','A client 4 hours after carotid endarterectomy with new hoarseness, difficulty swallowing, and increasing neck swelling|A client 1 day after laparoscopic cholecystectomy with right shoulder pain|A client 2 days after hernia repair who has not had a bowel movement|A client 6 hours after cataract surgery requesting eye drops','A','Neck swelling with hoarseness and dysphagia after carotid surgery suggests an expanding hematoma that can compress the airway. Shoulder pain after laparoscopy is referred pain from CO2 gas and is expected.','Integrated','Management of Care'),
('Set21-RN-2','Reduction of Risk Potential','Abdominal aortic aneurysm repair','single_best_answer','Reduction of Risk Potential • Abdominal aortic aneurysm repair • Multiple choice A client is 12 hours after open abdominal aortic aneurysm repair. Which finding requires the nurse''s immediate action?','Incisional pain rated 5/10|Urine output of 15 mL/hr for 2 consecutive hours|Hypoactive bowel sounds|Temperature of 99.5°F (37.5°C)','B','Aortic cross-clamping can reduce renal blood flow, and oliguria may signal acute kidney injury, hypovolemia, or graft problems. Hypoactive bowel sounds and low-grade fever are expected after major abdominal surgery.','Integrated','Adult Health'),
('Set21-RN-3','Pharmacological and Parenteral Therapies','Anticoagulant bridging','single_best_answer','Pharmacological and Parenteral Therapies • Anticoagulant bridging • Multiple choice A client with a new DVT started warfarin 2 days ago and is also receiving enoxaparin. The INR is 1.6. The client asks why both drugs are needed. What is the nurse''s best response?','"The enoxaparin will be stopped today because warfarin has started."|"Warfarin takes several days to work fully, so enoxaparin continues until your INR is in the target range for at least 24 hours."|"The two drugs cancel each other out."|"Enoxaparin is only for pain."','B','Warfarin''s full effect takes several days, and it can initially cause a brief hypercoagulable state. Overlap with a parenteral anticoagulant for at least 5 days, until the INR is therapeutic, prevents clot extension.','Integrated','Pharmacology'),
('Set21-RN-4','Pharmacological and Parenteral Therapies','Clonidine','single_best_answer','Pharmacological and Parenteral Therapies • Clonidine • Multiple choice A client taking clonidine for hypertension says, "I stopped my pills 2 days ago because they made my mouth dry." Which finding is the nurse most concerned about?','BP 212/118 mm Hg with headache and agitation|Mild dry mouth|HR 68/min|Mild drowsiness    ','A','Abrupt discontinuation of clonidine can cause rebound hypertension, which can be severe. Clonidine should be tapered. Dry mouth is a common side effect that can be managed.','Integrated','Pharmacology'),
('Set21-RN-5','Pharmacological and Parenteral Therapies','Nitrate tolerance','single_best_answer','Pharmacological and Parenteral Therapies • Nitrate tolerance • Multiple choice A client with stable angina uses a nitroglycerin transdermal patch. Which instruction helps prevent nitrate tolerance?','"Wear two patches at a time."|"Apply the patch in the morning and remove it at bedtime to allow a patch-free period of 10–12 hours."|"Never remove the patch."|"Apply the patch only when you have chest pain."','B','Continuous nitrate exposure leads to tolerance. A daily nitrate-free interval, usually overnight, maintains effectiveness.','Integrated','Pharmacology'),
('Set21-RN-6','Safety and Infection Control','Directly observed therapy','single_best_answer','Safety and Infection Control • Directly observed therapy • Multiple choice A client with active tuberculosis has a history of missing medication doses. Which strategy does the nurse anticipate the health department will use?','Stopping treatment until the client is motivated|Directly observed therapy, in which a health care worker watches the client take each dose|Doubling doses on the days the client remembers|Giving the full supply of pills to a neighbor','B','Directly observed therapy improves adherence, prevents drug resistance, and protects public health. Video-observed therapy is an option in many areas.','Integrated','Safety & Infection Control'),
('Set21-RN-7','Reduction of Risk Potential','Ventilator weaning','single_best_answer','Reduction of Risk Potential • Ventilator weaning • Multiple choice A client on a mechanical ventilator is undergoing a spontaneous breathing trial. Which finding indicates the nurse should stop the trial?','RR 22/min|SpO2 94%|RR 38/min with SpO2 86%, increased HR, and anxiety|Calm and following commands','C','Tachypnea above about 35/min, hypoxemia, a significant rise in heart rate or BP, diaphoresis, and agitation indicate trial failure. Ventilatory support is resumed and the provider notified.','Integrated','Adult Health'),
('Set21-RN-8','Pharmacological and Parenteral Therapies','IV phenytoin','single_best_answer','Pharmacological and Parenteral Therapies • IV phenytoin • Multiple choice The nurse is preparing to administer IV phenytoin. Which action is correct?','Mix it with 5% dextrose in water|Dilute it in 0.9% sodium chloride, infuse no faster than 50 mg/min in adults (using a filter per policy), and monitor ECG and BP|Give it as a rapid IV push|Give it through the same line as a dextrose infusion    ','B','Phenytoin precipitates in dextrose solutions. Rapid administration can cause hypotension and dysrhythmias. Fosphenytoin can be infused faster and causes less tissue irritation.','Integrated','Pharmacology'),
('Set21-RN-9','Reduction of Risk Potential','Plasmapheresis','single_best_answer','Reduction of Risk Potential • Plasmapheresis • Multiple choice A client with Guillain-Barré syndrome is receiving plasmapheresis. The client reports tingling around the mouth and in the fingers. What does the nurse suspect?','Hypocalcemia from the citrate anticoagulant|Hyperkalemia|Worsening of the Guillain-Barré syndrome|An expected finding that needs no action','A','Citrate used during plasmapheresis binds calcium and causes hypocalcemia. The nurse reports it, and calcium replacement and slowing the procedure may be needed. Hypotension and bleeding are other complications.','Integrated','Adult Health'),
('Set21-RN-10','Reduction of Risk Potential','Morning hyperglycemia','single_best_answer','Reduction of Risk Potential • Morning hyperglycemia • Multiple choice A client taking evening NPH insulin has high fasting glucose levels each morning. Which action best helps identify the cause?','Increase the evening NPH dose immediately|Check blood glucose around 0200–0300 for several nights|Stop the evening insulin|Check glucose only at bedtime','B','A low 0300 glucose suggests the Somogyi effect (rebound hyperglycemia after nighttime hypoglycemia), which requires less evening insulin. A normal or high 0300 glucose suggests the dawn phenomenon, which may require more insulin or different timing.','Integrated','Adult Health'),
('Set21-RN-11','Pharmacological and Parenteral Therapies','Antithyroid medications','single_best_answer','Pharmacological and Parenteral Therapies • Antithyroid medications • Multiple choice A client with Graves'' disease is taking methimazole. Which symptom should the nurse instruct the client to report immediately?','Weight gain|Sore throat and fever|Mild itching|Feeling cold','B','Methimazole and propylthiouracil can cause agranulocytosis. A sore throat or fever requires prompt CBC evaluation. PTU is preferred in the first trimester of pregnancy, and methimazole is preferred otherwise.','Integrated','Pharmacology'),
('Set21-RN-12','Physiological Adaptation','Perforated peptic ulcer','single_best_answer','Physiological Adaptation • Perforated peptic ulcer • Multiple choice A client with a history of peptic ulcer disease reports sudden, severe epigastric pain that spreads across the abdomen. The abdomen is rigid, and the client lies very still with knees drawn up. What does the nurse suspect?','Gastroesophageal reflux|Perforated ulcer with peritonitis|Irritable bowel syndrome|Gastroenteritis    ','B','Sudden severe pain with a board-like abdomen suggests perforation and chemical peritonitis, a surgical emergency. The client is kept NPO, and NG suction, IV fluids, and surgical evaluation follow.','Integrated','Adult Health'),
('Set21-RN-13','Reduction of Risk Potential','Gastrostomy tube dislodgement','single_best_answer','Reduction of Risk Potential • Gastrostomy tube dislodgement • Multiple choice A client''s percutaneous endoscopic gastrostomy (PEG) tube, placed 10 days ago, has come out. What should the nurse do?','Reinsert the tube immediately|Cover the site with a sterile dressing and notify the provider immediately|Insert an indwelling urinary catheter into the tract|Wait until the next day to report it','B','Before the tract matures (about 4–6 weeks), reinserting a tube blindly can place it in the peritoneal cavity and cause peritonitis. The provider must replace it, often under endoscopic or radiologic guidance.','Integrated','Adult Health'),
('Set21-RN-14','Safety and Infection Control','Dialysis catheter','single_best_answer','Safety and Infection Control • Dialysis catheter • Multiple choice A client has a tunneled central venous catheter used for hemodialysis. The nurse needs to give an IV antibiotic, and no peripheral access is available. What should the nurse do?','Use the dialysis catheter for the antibiotic|Contact the provider or follow policy, because dialysis catheters are reserved for dialysis|Flush the catheter with a large volume of saline first and then use it|Remove the heparin lock and use it freely','B','Dialysis catheters are locked with high-concentration heparin and reserved for dialysis to reduce infection and occlusion. Using them for other purposes requires specific orders.','Integrated','Safety & Infection Control'),
('Set21-RN-15','Pharmacological and Parenteral Therapies','Hydroxyurea','single_best_answer','Pharmacological and Parenteral Therapies • Hydroxyurea • Multiple choice An adult with sickle cell disease is starting hydroxyurea. Which instruction should the nurse include?','"No blood tests are needed."|"You''ll need regular blood counts, and you should use effective contraception because the drug can harm a developing baby."|"It cures sickle cell disease."|"Take it only during pain crises."','B','Hydroxyurea increases fetal hemoglobin and reduces crises. It can cause bone marrow suppression and is teratogenic, so CBC monitoring and contraception are required. It is taken daily.','Integrated','Pharmacology'),
('Set21-RN-16','Pharmacological and Parenteral Therapies','Tamoxifen','single_best_answer','Pharmacological and Parenteral Therapies • Tamoxifen • Multiple choice A client is taking tamoxifen after breast cancer treatment. Which symptom should the nurse instruct the client to report?','Hot flashes|Abnormal vaginal bleeding or unilateral leg pain and swelling|Mild fatigue|Occasional headache    ','B','Tamoxifen increases the risk of endometrial cancer and venous thromboembolism. Hot flashes are a common, expected side effect.','Integrated','Pharmacology'),
('Set21-RN-17','Health Promotion and Maintenance','HIV pre-exposure prophylaxis','single_best_answer','Health Promotion and Maintenance • HIV pre-exposure prophylaxis • Multiple choice A client starting HIV pre-exposure prophylaxis (PrEP) asks about follow-up. Which response by the nurse is accurate?','"No follow-up is needed once you start."|"You''ll need HIV and STI testing and kidney function checks regularly, usually every 3 months for oral PrEP."|"PrEP protects against all sexually transmitted infections."|"You can take it only when you remember."','B','Regular HIV testing ensures infection hasn''t occurred (which would require full treatment). Other STI screening and kidney monitoring are also needed. PrEP does not prevent other STIs, so condoms are still recommended.','Integrated','Fundamentals'),
('Set21-RN-18','Reduction of Risk Potential','Amniocentesis','single_best_answer','Reduction of Risk Potential • Amniocentesis • Multiple choice An Rh-negative client with an Rh-positive partner had an amniocentesis at 16 weeks. Which action is most important after the procedure?','Encourage strict bed rest for a week|Administer Rh(D) immune globulin as prescribed and teach the client to report leaking fluid, bleeding, cramping, or fever|Give a laxative|Schedule a repeat amniocentesis in 1 week','B','Amniocentesis can cause fetal-maternal blood mixing, so Rh-negative clients receive Rh immune globulin. Complications include rupture of membranes, infection, and pregnancy loss.','Integrated','Adult Health'),
('Set21-RN-19','Physiological Adaptation','Pediatric nephrotic syndrome','single_best_answer','Physiological Adaptation • Pediatric nephrotic syndrome • Multiple choice A 4-year-old with nephrotic syndrome is receiving prednisone. Which finding indicates the treatment is working?','Increasing proteinuria|Decreasing edema and urine protein, with weight returning to baseline|Worsening periorbital swelling|Serum albumin decreasing further  ','B','Remission is shown by reduced proteinuria and resolving edema as albumin rises. Children on steroids are at increased risk of infection, and live vaccines are avoided.','Integrated','Adult Health')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 keyarr:=string_to_array(r.keys,',');
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method)
 values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Each distractor must be evaluated against the clinical task and source rationale.','Identify the task, interpret the cues, and compare every option with the safest evidence-based RN response.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,'{}'::jsonb,case when r.item_type='multiple_response' then 'plus_minus' else 'zero_one' end)
 on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,source_id=excluded.source_id,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid; n:=0;
 for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop;
 select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid;
 if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source key/options passed deterministic consistency validation; clinical review pending.' where id=qvid;
end loop;
end $$;
commit;